var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},MAPA:{nome:`MAPA`,cor:`#7F1D1D`},UFMT:{nome:`UFMT`,cor:`#92400E`},UFBA:{nome:`UFBA`,cor:`#1D4ED8`},UFPE:{nome:`UFPE`,cor:`#065F46`},UFPR:{nome:`UFPR`,cor:`#6D28D9`},UFRGS:{nome:`UFRGS`,cor:`#B91C1C`},UFRPE:{nome:`UFRPE`,cor:`#0369A1`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},n={cirurgia_bovina:{nome:`Cirurgia Bovina`,eixo:`cga`},cirurgia_equina:{nome:`Cirurgia Equina`,eixo:`cga`},cirurgia_ovina_caprina:{nome:`Cirurgia Ovina e Caprina`,eixo:`cga`},cirurgia_suina:{nome:`Cirurgia Suína`,eixo:`cga`},anestesia_ga:{nome:`Anestesia em Grandes Animais`,eixo:`cga`},ortopedia_ga:{nome:`Ortopedia em Grandes Animais`,eixo:`cga`},cirurgia_abdominal_ga:{nome:`Cirurgia Abdominal`,eixo:`cga`},cirurgia_toracica_ga:{nome:`Cirurgia Torácica`,eixo:`cga`},cirurgia_tegumentar_ga:{nome:`Cirurgia Tegumentar`,eixo:`cga`},complicacoes_cirurgicas_ga:{nome:`Complicações Cirúrgicas`,eixo:`cga`},instrumentacao_ga:{nome:`Instrumentação para Grandes Animais`,eixo:`cga`},pos_operatorio_ga:{nome:`Pós-Operatório em Grandes Animais`,eixo:`cga`}},r=[{id:`cga-c-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Cirurgia de Grandes Animais 2023`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Rumenotomia`,dificuldade:`medio`,enunciado:`Sobre a técnica de rumenotomia em bovinos, assinale a alternativa CORRETA:`,alternativas:[`A incisão deve ser realizada no flanco esquerdo, na fossa paralombar, entre a última costela e a tuberosidade do quadril.`,`O rúmen deve ser suturado à pele com sutura contínua simples para evitar contaminação peritoneal.`,`A abertura do rúmen deve ser realizada com bisturi elétrico para melhor hemostasia.`,`A cicatrização do rúmen ocorre por primeira intenção, sem formação de tecido de granulação.`,`O acesso ao rúmen pode ser realizado indiferentemente pelo flanco direito ou esquerdo.`],resposta_correta:`A`,explicacao:`A rumenotomia é classicamente realizada no flanco esquerdo, fossa paralombar, onde o rúmen está em contato com a parede abdominal. O rúmen é fixado à pele com sutura em bolsa (não contínua simples). Prefere-se lâmina de bisturi convencional (não elétrico). A cicatrização do rúmen é por segunda intenção devido à contaminação. O acesso preferencial é o flanco esquerdo.`},{id:`cga-c-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Cesariana bovina`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre cesariana em bovinos:`,alternativas:[`VERDADEIRO`,`FALSO`],vf:!0,enunciado_complementar:`Na cesariana em bovinos, o acesso pelo flanco direito é preferido quando o feto está em posição dorso-sacral, pois permite melhor manipulação do útero.`,resposta_correta:`B`,explicacao:`O acesso para cesariana em bovinos é classicamente pelo flanco esquerdo, independentemente da posição fetal. O flanco esquerdo é preferido porque o rúmen desloca o intestino, facilitando o acesso ao útero. A posição fetal dorso-sacral é indicação de cesariana, mas não altera o lado de acesso.`},{id:`cga-c-003`,banca:`FCC`,ano:2021,prova:`FCC — Médico Veterinário 2021`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Desacornamento`,dificuldade:`facil`,enunciado:`Em relação ao desacornamento de bovinos, assinale a alternativa correta:`,alternativas:[`O desacornamento a frio com serra de Guthrie é recomendado para bezerros acima de 60 dias de idade.`,`A termocauterização da broca do corno é o método mais indicado para bezerros até 2 meses de idade.`,`O uso de anel elástico é o método preferido para desacornamento em bovinos adultos.`,`O desacornamento químico com hidróxido de sódio é seguro e não necessita de contenção química.`,`O desacornamento cirúrgico com serra em bovinos adultos não necessita de hemostasia complementar.`],resposta_correta:`B`,explicacao:`A termocauterização da broca do corno é recomendada para bezerros até 2 meses de idade, quando a broca ainda não se fixou totalmente ao osso frontal. O desacornamento a frio (A) é indicado para bezerros mais novos (até 1 mês). O anel elástico (C) não é recomendado para adultos. O desacornamento químico (D) requer contenção e cuidados. O desacornamento em adultos (E) necessita hemostasia.`},{id:`cga-c-004`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Castração bovina`,dificuldade:`medio`,enunciado:`Sobre a castração em bovinos, é correto afirmar:`,alternativas:[`A castração com pinça de Burdizzo pode ser realizada sem anestesia, pois o animal não sente dor.`,`A castração aberta com bisturi é preferida em bovinos adultos por permitir melhor hemostasia.`,`O método de castração com elastrador é recomendado para bezerros até 3 semanas de idade.`,`A castração química com cloreto de zinco é um método reversível.`,`A castração com tesoura de Serra é indicada para bovinos acima de 200 kg.`],resposta_correta:`C`,explicacao:`O elastrador é recomendado para bezerros até 3 semanas de idade, quando o escroto é pequeno e a necrose isquêmica ocorre rapidamente. A pinça de Burdizzo (A) causa dor e requer anestesia local. A castração aberta (B) em adultos tem maior risco de hemorragia. A castração química (D) é irreversível. A tesoura de Serra (E) é indicada para animais jovens.`},{id:`cga-c-005`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia Veterinária 2020`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Herniorrafia bovina`,dificuldade:`dificil`,enunciado:`Sobre a herniorrafia inguinal em bovinos, assinale a alternativa INCORRETA:`,alternativas:[`A hérnia inguinal em bovinos machos é mais frequente após a castração.`,`O tratamento cirúrgico deve ser realizado o mais precocemente possível para evitar estrangulamento.`,`A técnica de herniorrafia com tela de polipropileno está indicada em hérnias de grande porte.`,`O acesso cirúrgico é realizado por incisão ventral mediana na região inguinal.`,`A recidiva é mais frequente quando se utiliza apenas sutura simples sem reforço protético.`],resposta_correta:`D`,explicacao:`O acesso para herniorrafia inguinal em bovinos é realizado por incisão na região inguinal (não ventral mediana), acompanhando o trajeto do canal inguinal. A ventral mediana é utilizada para outras cirurgias abdominais. As demais alternativas estão corretas.`},{id:`cga-c-006`,banca:`CRMV`,ano:2022,prova:`CRMV — Prova de Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_bovina`,subtopico:`Otoplastia bovina`,dificuldade:`medio`,enunciado:`A otoplastia em bovinos é indicada para correção de:`,alternativas:[`Hematoma auricular crônico com deformidade da orelha.`,`Otite externa bacteriana aguda.`,`Ceruminose excessiva sem inflamação.`,`Presença de corpo estranho no canal auditivo.`,`Parasitismo auricular por Rhabditis sp.`],resposta_correta:`A`,explicacao:`A otoplastia é indicada para correção de deformidades auriculares, como hematoma auricular crônico que levou a fibrose e deformidade. Otite externa (B), ceruminose (C), corpo estranho (D) e parasitismo (E) são tratados clinicamente ou com remoção simples, sem necessidade de otoplastia.`},{id:`cga-c-007`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso Professor 2021`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Oftalmologia bovina`,dificuldade:`dificil`,enunciado:`Sobre o tratamento cirúrgico de úlcera de córnea perfurante em bovinos, é correto afirmar:`,alternativas:[`A ceratoplastia lamelar é o tratamento de escolha para úlceras perfurantes centrais.`,`O transplante de membrana nictitante está indicado como cobertura para úlceras perfurantes.`,`A enucleação é sempre indicada em úlceras perfurantes, independentemente do tamanho.`,`O uso de colírios com corticosteroides é fundamental no pós-operatório imediato.`,`A sutura da córnea com fio de nylon 10-0 é suficiente para úlceras perfurantes grandes.`],resposta_correta:`B`,explicacao:`O transplante de membrana nictitante (terceira pálpebra) é utilizado como enxerto de cobertura para úlceras perfurantes, fornecendo suporte estrutural e vascularização. A ceratoplastia lamelar (A) não é indicada para perfurantes. A enucleação (C) é último recurso. Corticosteroides (D) são contraindicados em úlceras. A sutura corneana (E) não é suficiente sozinha.`},{id:`cga-c-008`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência Cirurgia 2023`,tipo:`residencia`,topico:`cirurgia_bovina`,subtopico:`Timpanismo ruminal`,dificuldade:`medio`,enunciado:`Em caso de timpanismo espumoso agudo em bovinos, a trocarotomia está indicada quando:`,alternativas:[`O animal apresenta distensão abdominal leve e continua alimentando-se normalmente.`,`O tratamento clínico com antiespumantes orais não é eficaz e há risco de asfixia.`,`O animal apresenta timpanismo moderado sem desconforto respiratório.`,`O manejo alimentar corrigido resolve o quadro em até 2 horas.`,`O animal apresenta apenas eructação reduzida sem distensão abdominal.`],resposta_correta:`B`,explicacao:`A trocarotomia (rumenostomia de emergência) está indicada em casos de timpanismo espumoso agudo refratário ao tratamento clínico, quando há risco iminente de asfixia. Quadros leves (A, C) e responsivos ao manejo (D) não requerem intervenção cirúrgica. Eructação reduzida sem distensão (E) não é indicação.`},{id:`cga-c-009`,banca:`USP`,ano:2022,prova:`USP — Residência em Cirurgia 2022`,tipo:`residencia`,topico:`cirurgia_bovina`,subtopico:`Reticulectomia`,dificuldade:`dificil`,enunciado:`A reticulectomia em bovinos está indicada no tratamento de:`,alternativas:[`Timpanismo espumoso crônico refratário.`,`Pericardite traumática por corpo estranho reticular.`,`Deslocamento de abomaso à esquerda.`,`Obstrução intestinal por fitobezoar.`,`Urolitíase em bovinos machos.`],resposta_correta:`B`,explicacao:`A reticulectomia está indicada na pericardite traumática por corpo estranho reticular (geralmente arame), permitindo a remoção do corpo estranho e descompressão. Timpanismo (A) é tratado com rumenostomia. DAE (C) tem técnica específica. Obstrução (D) e urolitíase (E) não envolvem o retículo.`},{id:`cga-c-010`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso Veterinário 2021`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Sutura de pele bovina`,dificuldade:`facil`,enunciado:`Qual o tipo de sutura mais utilizado para fechamento de pele em bovinos?`,alternativas:[`Sutura de Donati modificada (colchoada horizontal).`,`Sutura contínua intradérmica.`,`Sutura em pontos separados simples com fio de nylon.`,`Agrafagem com grampos metálicos.`,`Sutura de Schmieden.`],resposta_correta:`A`,explicacao:`A sutura de Donati modificada (colchoada horizontal) é a mais utilizada para fechamento de pele em bovinos por proporcionar boa eversão das bordas, resistência adequada e reduzir a tensão sobre os pontos. Sutura contínua (B) pode isquemiar. Pontos simples (C) têm menor resistência. Agrafagem (D) é menos comum em grandes animais. Schmieden (E) é mais usada em cães.`},{id:`cga-c-011`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Federal Agropecuário 2023`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Deslocamento de abomaso`,dificuldade:`medio`,enunciado:`Sobre o tratamento cirúrgico do deslocamento de abomaso à esquerda (DAE) em bovinos, é correto afirmar:`,alternativas:[`A técnica de toggle pin é realizada com o animal em estação, sem necessidade de laparotomia.`,`A técnica de omentopexia via flanco direito é a mais utilizada e apresenta maior taxa de sucesso.`,`O DAE sempre requer tratamento cirúrgico, não havendo resposta ao tratamento clínico.`,`A abomasopexia percutânea com parafusos é contraindicada em vacas leiteiras.`,`O DAE ocorre mais frequentemente em vacas no início da lactação devido ao balanço energético positivo.`],resposta_correta:`A`,explicacao:`A técnica de toggle pin permite a correção do DAE com o animal em estação, utilizando pinos transfixantes para fixar o abomaso à parede abdominal. A omentopexia (B) é feita pelo flanco esquerdo. O DAE (C) pode responder a tratamento clínico em casos leves. Parafusos (D) são utilizados. O DAE (E) ocorre em balanço energético negativo.`},{id:`cga-c-012`,banca:`ENAV`,ano:2024,prova:`ENAV — Especial 2024`,tipo:`enav`,topico:`cirurgia_bovina`,subtopico:`Urolitíase bovina`,dificuldade:`dificil`,enunciado:`Em bovinos machos com urolitíase obstrutiva, a cistostomia de emergência está indicada quando:`,alternativas:[`O animal apresenta hematúria leve sem obstrução completa.`,`Há ruptura uretral com uroabdômen e azotemia severa.`,`O cálculo está localizado na fossa isquiática e pode ser removido por uretrotomia.`,`O animal apresenta disúria leve com cristalúria.`,`O uretrostomia perineal é contraindicada pelo tamanho do cálculo.`],resposta_correta:`B`,explicacao:`A cistostomia de emergência está indicada em casos de ruptura uretral com uroabdômen e azotemia, permitindo descompressão da bexiga e correção do desequilíbrio hidroeletrolítico antes de procedimentos definitivos. Hematúria (A) e disúria (D) não requerem cirurgia. Cálculo na fossa (C) é acessível por uretrotomia. A contraindicação de uretrostomia (E) não indica cistostomia isoladamente.`},{id:`cga-c-013`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso Veterinário 2020`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Contenção mecânica`,dificuldade:`facil`,enunciado:`Para contenção mecânica de bovinos em procedimentos cirúrgicos de campo, o método mais utilizado é:`,alternativas:[`Tronco de contenção (squeeze chute) com decúbito lateral em valeta.`,`Anestesia geral inalatória com isoflurano em sala cirúrgica.`,`Contenção química com xilazina em dose dissociativa.`,`Maca cirúrgica suspensa com trela.`,`Contenção em pé com apenas suporte manual.`],resposta_correta:`A`,explicacao:`O tronco de contenção associado ao decúbito lateral em valeta é o método padrão para cirurgia de campo em bovinos. Anestesia inalatória (B) requer infraestrutura hospitalar. Xilazina (C) é complementar, não substitui contenção mecânica. Maca (D) não é prática em campo. Suporte manual (E) é insuficiente para grandes animais.`},{id:`cga-c-014`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência Veterinária 2022`,tipo:`residencia`,topico:`cirurgia_bovina`,subtopico:`Correção de prolapso retal`,dificuldade:`medio`,enunciado:`Na correção de prolapso retal em bovinos, a técnica de retalho retal está indicada quando:`,alternativas:[`O prolapso é recente (menos de 6 horas) e o tecido está viável.`,`Há necrose extensa da mucosa retal e não é possível a redução manual.`,`O prolapso é menor que 10 cm e sem edema.`,`O animal apresenta tenesmo leve sem prolapso visível.`,`O prolapso recidivou após redução manual simples.`],resposta_correta:`B`,explicacao:`A técnica de retalho retal (ressecção mucosa) está indicada quando há necrose da mucosa retal, impossibilitando a redução manual. Pro lapsos recentes (A) e pequenos (C) são reduzidos manualmente. Tenesmo sem prolapso (D) é tratado clinicamente. Recidiva simples (E) pode ser resolvida com redução e sutura.`},{id:`cga-c-015`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Craniotomia bovina`,dificuldade:`dificil`,enunciado:`A craniotomia frontal em bovinos está indicada para:`,alternativas:[`Remoção de abscesso pericrâniano superficial.`,`Drenagem de seio frontal acometido por actinomicose crônica.`,`Correção de fratura de chifre com exposição óssea.`,`Remoção de corpo estranho subcutâneo na região frontal.`,`Tratamento de hematoma auricular.`],resposta_correta:`B`,explicacao:`A craniotomia frontal é indicada para drenagem e curetagem do seio frontal em casos de actinomicose ou outras sinusites crônicas refratárias. Abscessos superficiais (A) são drenados por incisão simples. Fraturas (C) e corpos estranhos (D) têm técnicas específicas menos invasivas. Hematoma auricular (E) não envolve o crânio.`},{id:`cga-c-016`,banca:`UFPR`,ano:2023,prova:`UFPR — Professor 2023`,tipo:`concurso`,topico:`cirurgia_bovina`,subtopico:`Queiloplastia bovina`,dificuldade:`medio`,enunciado:`A queiloplastia em bovinos é indicada para correção de:`,alternativas:[`Paralisia do nervo facial com ptose labial.`,`Líquen plano oral.`,`Estomatite vesicular.`,`Úlceras orais por fotossensibilização.`,`Papilomatose oral.`],resposta_correta:`A`,explicacao:`A queiloplastia é indicada para correção de deformidades labiais, como ptose por paralisia do nervo facial, que compromete a preensão de alimento. Líquen plano (B), estomatite (C), úlceras por fotossensibilização (D) e papilomatose (E) são condições clínicas tratadas clinicamente ou com outros procedimentos.`},{id:`cga-c-017`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_bovina`,subtopico:`Drenagem torácica`,dificuldade:`medio`,enunciado:`A toracocentese em bovinos é realizada no espaço intercostal:`,alternativas:[`6º ou 7º à direita, acima da linha do cotovelo.`,`8º ou 9º à esquerda, abaixo da linha do cotovelo.`,`3º ou 4º à direita, na região esternal.`,`10º ou 11º bilateralmente, no flanco.`,`5º ou 6º à esquerda, na região axilar.`],resposta_correta:`A`,explicacao:`A toracocentese em bovinos é classicamente realizada no 6º ou 7º espaço intercostal à direita, acima da linha do cotovelo, onde há maior volume de líquido pleural acumulado. O lado direito é preferido devido à posição do coração.`},{id:`cga-c-018`,banca:`ENAV`,ano:2023,prova:`ENAV — Cirurgia Equina 2023`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Cólica — Deslocamento`,dificuldade:`medio`,enunciado:`Sobre o deslocamento dorsal do cólon grande em equinos, é correto afirmar:`,alternativas:[`É a causa mais comum de cólica em equinos adultos e geralmente responde ao tratamento cirúrgico.`,`O diagnóstico é confirmado por retocção retal, onde se palpam as alças do cólon deslocadas sobre o ceco.`,`O tratamento clínico com fluidoterapia e analgesia é suficiente em todos os casos.`,`A recorrência é rara após o tratamento cirúrgico bem-sucedido.`,`A descompressão intestinal por sonda nasogástrica resolve definitivamente o deslocamento.`],resposta_correta:`B`,explicacao:`O diagnóstico de deslocamento dorsal do cólon grande é confirmado por retocção retal, onde se palpam as bandas do cólon deslocadas dorsalmente sobre o ceco. A cólica por deslocamento (A) não é a mais comum (impactação é mais frequente). Nem todos os casos (C) respondem ao clínico. A recorrência (D) pode ocorrer. Sonda nasogástrica (E) não resolve deslocamento.`},{id:`cga-c-019`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso MAPA 2022`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Cólica — Torsão`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre volvulo do intestino delgado em equinos:`,alternativas:[`VERDADEIRO`,`FALSO`],vf:!0,enunciado_complementar:`O volvulo do intestino delgado em equinos apresenta mortalidade cirúrgica superior a 50% devido à rápida progressão de necrose intestinal e desordens metabólicas severas.`,resposta_correta:`A`,explicacao:`O volvulo do intestino delgado em equinos é uma das causas mais graves de cólica, com mortalidade cirúrgica elevada (>50%) devido à rápida necrose intestinal, endotoxemia e choque. A descompressão e ressecção intestinal são necessárias, mas o prognóstico é reservado.`},{id:`cga-c-020`,banca:`FCC`,ano:2021,prova:`FCC — Médico Veterinário 2021`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Cólica — Impactação`,dificuldade:`facil`,enunciado:`A impactação do cólon grande em equinos é mais frequente em:`,alternativas:[`Flexura pélvica do cólon descendente (small colon).`,`Íleo e ceco.`,`Duodeno e jejuno.`,`Cólon ascendente (colôn grande).`,`Reto e cólon descendente.`],resposta_correta:`A`,explicacao:`A flexura pélvica do cólon descendente (small colon) é o local mais comum de impactação em equinos, devido ao diâmetro reduzido e à mudança de direção do trânsito intestinal. O colôn grande (D) também é acometido, mas a flexura pélvica é mais frequente.`},{id:`cga-c-021`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Artroscopia equina`,dificuldade:`medio`,enunciado:`Sobre artroscopia em equinos, assinale a alternativa CORRETA:`,alternativas:[`A artroscopia é indicada apenas para diagnóstico, não sendo possível realizar procedimentos terapêuticos.`,`O joelho (carpo) e o boleto (fetlock) são as articulações mais frequentemente submetidas à artroscopia.`,`A artroscopia em equinos requer anestesia geral com isoflurano, sendo impossível em estação.`,`O uso de artroscopia é contraindicado em lesões osteocondrais.`,`A artroscopia é um procedimento exclusivamente experimental em equinos.`],resposta_correta:`B`,explicacao:`O joelho (carpo) e o boleto (fetlock) são as articulações mais frequentemente submetidas à artroscopia em equinos, para remoção de fragmentos osteocondrais, sinovectomia e lavagem. A artroscopia (A) é diagnóstica e terapêutica. Pode ser realizada em estação (C) em alguns casos. É indicada para lesões osteocondrais (D). É rotina (E).`},{id:`cga-c-022`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Neurectomia palmar`,dificuldade:`dificil`,enunciado:`A neurectomia palmar digital em equinos está indicada para:`,alternativas:[`Tratamento de naviculite crônica refratária ao tratamento clínico.`,`Correção de desvio angular em potros.`,`Tratamento de fratura de sesamoide proximal.`,`Correção de contração de tendão flexor digital profundo.`,`Tratamento de artrite séptica aguda.`],resposta_correta:`A`,explicacao:`A neurectomia palmar digital é indicada para naviculite (síndrome do navicular) crônica refratária, promovendo analgesia permanente dos dígitos. Não é indicada para desvios angulares (B), fraturas (C), contrações tendíneas (D) ou artrite séptica (E), que requerem outros tratamentos.`},{id:`cga-c-023`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_equina`,subtopico:`Cirurgia podal`,dificuldade:`medio`,enunciado:`Na cirurgia podal de equinos, a aplicação de ferradura com pinça elevada está indicada para:`,alternativas:[`Reduzir a pressão sobre o tendão flexor digital profundo em casos de laminite.`,`Aumentar a tração em cavalos de corrida.`,`Corrigir desvios angulares em potros.`,`Tratar fraturas de falange distal.`,`Prevenir arranhões em terrenos lamacentos.`],resposta_correta:`A`,explicacao:`A ferradura com pinça elevada (rolled toe ou rockered toe) reduz a pressão sobre o tendão flexor digital profundo e a articulação interfalângica distal, sendo indicada em laminite e síndrome do navicular. Não tem relação com tração (B), desvios (C), fraturas (D) ou arranhões (E).`},{id:`cga-c-024`,banca:`UFMG`,ano:2021,prova:`UFMG — Concursos 2021`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Tenotomia do ligamento nucal`,dificuldade:`dificil`,enunciado:`A tenotomia do ligamento nucal em equinos está indicada para:`,alternativas:[`Correção de extensão excessiva do membro torácico (overreach).`,`Tratamento de luxação atlantoaxial.`,`Correção de deformidade flexural do boleto em neonatos.`,`Tratamento de miopatia fibrótica (sweeney).`,`Correção de torticolo congênito.`],resposta_correta:`C`,explicacao:`A tenotomia do ligamento nucal é indicada para correção de deformidade flexural congênita do boleto (fetlock) em neonatos, quando há contratura do tendão flexor. Não está indicada para overreach (A), luxação atlantoaxial (B), miopatia fibrótica (D) ou torticolo (E).`},{id:`cga-c-025`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_equina`,subtopico:`Reparo de hérnia inguinal`,dificuldade:`medio`,enunciado:`A hérnia inguinal estrangulada em equinos machos é uma emergência cirúrgica que requer:`,alternativas:[`Redução imediata via inguinotomia com avaliação da viabilidade intestinal.`,`Apenas contenção química e monitoramento por 24 horas.`,`Orquiectomia bilateral imediata sem exploração abdominal.`,`Descompressão por sonda nasogástrica e antibioticoterapia.`,`Aplicação de bandagem compressiva na região inguinal.`],resposta_correta:`A`,explicacao:`A hérnia inguinal estrangulada requer intervenção cirúrgica imediata (inguinotomia) para descompressão e avaliação da viabilidade intestinal, com possível ressecção se houver necrose. Monitoramento (B) é insuficiente. Orquiectomia (C) não resolve a hérnia. Sonda (D) e bandagem (E) não tratam estrangulamento.`},{id:`cga-c-026`,banca:`USP`,ano:2022,prova:`USP — Pós-Graduação 2022`,tipo:`pos`,topico:`cirurgia_equina`,subtopico:`Sinovite séptica`,dificuldade:`dificil`,enunciado:`No tratamento cirúrgico de sinovite séptica em equinos, a lavagem artroscópica está indicada:`,alternativas:[`Apenas após 48 horas de antibioticoterapia sistêmica isolada.`,`Quando há falha da lavagem percutânea ou presença de debris intra-articular.`,`Somente em articulações distais (falanges e sesamoides).`,`Quando o animal apresenta febre superior a 40°C.`,`Apenas em potros neonatos com sepse neonatal.`],resposta_correta:`B`,explicacao:`A lavagem artroscópica está indicada quando a lavagem percutânea falhou ou quando há debris, fibrina e fragmentos intra-articular que impedem a resolução do quadro infeccioso. Não é limitada por tempo de antibioticoterapia (A), localização (C), febre (D) ou idade (E).`},{id:`cga-c-027`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Osteossíntese em equinos`,dificuldade:`medio`,enunciado:`Na osteossíntese de fraturas em equinos, a fixação com placa e parafusos está indicada para:`,alternativas:[`Fraturas diafisárias de tíbia em cavalos adultos de grande porte.`,`Fraturas de falange distal em potros.`,`Fraturas de costelas em equinos de qualquer idade.`,`Fraturas de vértebras torácicas.`,`Fraturas de pelve em éguas gestantes.`],resposta_correta:`A`,explicacao:`A fixação com placa e parafusos (osteoestabilização) é indicada para fraturas diafisárias de tíbia em cavalos adultos, onde a aplicação de placas em ponte ou placas de compressão é viável. Fraturas de falange (B) podem ser fixadas com parafusos. Costelas (C), vértebras (D) e pelve (E) geralmente não requerem osteossíntese.`},{id:`cga-c-028`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal Agropecuário 2023`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Fístula de garrote`,dificuldade:`facil`,enunciado:`A fístula de garrote (fístula da withers) em equinos é causada por:`,alternativas:[`Infecção crônica do ligamento supraspinoso com formação de abscesso.`,`Fratura da vértebra torácica com exposição óssea.`,`Hérnia diafragmática com comunicação pleuroperitoneal.`,`Tumor de glândula sudorípara na região dorsal.`,`Ruptura do tendão do músculo bíceps braquial.`],resposta_correta:`A`,explicacao:`A fístula de garrote é uma condição crônica caracterizada por infecção e abscesso no ligamento supraspinoso (nucal) na região dos withers (garrote), geralmente associada a trauma por sela mal ajustada. As outras alternativas não descrevem essa condição.`},{id:`cga-c-029`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Castração equina`,dificuldade:`medio`,enunciado:`Na castração de equinos em estação com sedação, a técnica preferida é:`,alternativas:[`Castração aberta com hemostasia por ligadura do cordão espermático.`,`Castração com pinça de Burdizzo sem incisão.`,`Castração com elastrador e bandas elásticas.`,`Castração química com formalina intra-testicular.`,`Castração com bisturi elétrico sem ligadura.`],resposta_correta:`A`,explicacao:`A castração aberta com hemostasia por ligadura do cordão espermático é a técnica padrão para equinos em estação, permitindo controle adequado de hemorragia e prevenção de prolapso. Pinça de Burdizzo (B) é mais usada em bovinos. Elastrador (C) é limitado a neonatos. Formalina (D) é experimental. Sem ligadura (E) apresenta risco de hemorragia.`},{id:`cga-c-030`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_equina`,subtopico:`Desmotomia do ligamento suspensório`,dificuldade:`dificil`,enunciado:`A desmotomia do ligamento suspensório acessório em equinos está indicada para:`,alternativas:[`Tratamento de contração do tendão flexor digital superficial.`,`Correção de desvio angular em potros.`,`Tratamento de ruptura do tendão flexor digital profundo.`,`Correção de luxação patelar.`,`Tratamento de hematomas subcutâneos.`],resposta_correta:`A`,explicacao:`A desmotomia do ligamento suspensório acessório (check ligament desmotomy) é indicada para tratamento de contração do tendão flexor digital superficial, reduzindo a tensão sobre o tendão. Não é indicada para desvios (B), ruptura do profundo (C), luxação patelar (D) ou hematomas (E).`},{id:`cga-c-031`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Rinotomia equina`,dificuldade:`medio`,enunciado:`A rinotomia em equinos está indicada para:`,alternativas:[`Remoção de tumores etmoidais e hematomas.`,`Tratamento de rinite alérgica sazonal.`,`Correção de desvio de septo nasal congênito.`,`Tratamento de sinusite bacteriana aguda.`,`Remoção de corpo estranho nasal superficial.`],resposta_correta:`A`,explicacao:`A rinotomia (ou sinorinotomia) é indicada para acesso cirúrgico à cavidade nasal e seios paranasais para remoção de tumores etmoidais, hematomas e outras massas. Rinite alérgica (B) é tratada clinicamente. Desvio de septo (C) é corrigido por septoplastia. Sinusite (D) pode ser tratada com trephinação. Corpo estranho superficial (E) pode ser removido por endoscopia.`},{id:`cga-c-032`,banca:`UFPR`,ano:2023,prova:`UFPR — Professor 2023`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Enterólito equino`,dificuldade:`medio`,vf:!1,enunciado:`Os enterólitos em equinos são mais frequentemente encontrados no:`,alternativas:[`Cólon ventral direito (right ventral colon).`,`Intestino delgado (jejuno).`,`Ceco.`,`Reto.`,`Cólon dorsal esquerdo.`],resposta_correta:`A`,explicacao:`Os enterólitos em equinos são mais frequentemente encontrados no cólon ventral direito, onde o conteúdo intestinal é mais denso e a formação de cálculos é favorecida. Podem causar cólica obstrutiva e requerem remoção cirúrgica por enterotomia.`},{id:`cga-c-033`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_equina`,subtopico:`Osteocondrose equina`,dificuldade:`dificil`,enunciado:`O tratamento cirúrgico da osteocondrose (OCD) em equinos envolve:`,alternativas:[`Artroscopia para remoção de fragmentos osteocondrais e curetagem da lesão.`,`Osteossíntese com parafusos canulados para fixação do fragmento.`,`Artrodese da articulação acometida.`,`Ressecção do membro afetado.`,`Aplicação de corticosteroides intra-articulares sem desbridamento.`],resposta_correta:`A`,explicacao:`O tratamento cirúrgico da OCD é a artroscopia com remoção de fragmentos osteocondrais e curetagem da lesão, promovendo cicatrização por fibrocartilagem. Fixação (B) é raramente indicada. Artrodese (C) é para articulações destruídas. Ressecção (D) não é indicada. Corticoides (E) sem desbridamento não resolvem.`},{id:`cga-c-034`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_equina`,subtopico:`Laparotomia exploratória`,dificuldade:`medio`,enunciado:`Na laparotomia exploratória em equinos para investigação de cólica, o acesso preferencial é:`,alternativas:[`Laparotomia ventral mediana (linha branca) com o animal em decúbito dorsal.`,`Laparotomia pelo flanco direito com o animal em estação.`,`Laparotomia pelo flanco esquerdo em decúbito lateral.`,`Laparoscopia diagnóstica sem incisão ampla.`,`Laparotomia subcostal bilateral.`],resposta_correta:`A`,explicacao:`A laparotomia ventral mediana (linha branca) com o animal em decúbito dorsal é o acesso padrão para laparotomia exploratória em equinos com cólica, permitindo acesso a todos os segmentos do trato gastrointestinal. Flanco direito (B) é usado para cirurgias específicas. Flanco esquerdo (C) é mais para bovinos. Laparoscopia (D) tem indicações limitadas.`},{id:`cga-c-035`,banca:`ENAV`,ano:2023,prova:`ENAV — Ovinos e Caprinos 2023`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Cesariana ovina`,dificuldade:`medio`,enunciado:`Sobre a cesariana em ovelhas, é correto afirmar:`,alternativas:[`O acesso pelo flanco esquerdo é preferido, semelhante à técnica bovina.`,`A cesariana é indicada quando há apresentação fetal anormal não corrigível por manipulação externa.`,`A anestesia geral inalatória é obrigatória para cesariana em ovelhas.`,`O útero ovino deve ser suturado com sutura em pontos separados simples.`,`A cesariana em ovelhas tem taxa de sobrevival fetal superior a 90%.`],resposta_correta:`B`,explicacao:`A cesariana em ovelhas está indicada quando há apresentação fetal anormal (transversa, dorso-sacral) que não pode ser corrigida por manipulação. O acesso preferido é ventral mediana (não flanco, como em bovinos). Anestesia local regional é suficiente. O útero é suturado com padrão Cushing ou Lembert. A sobrevival fetal depende do tempo decorrido.`},{id:`cga-c-036`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso Veterinário 2022`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Castração ovina`,dificuldade:`facil`,enunciado:`O método de castração mais recomendado para cordeiros até 7 dias de idade é:`,alternativas:[`Elastrador com banda elástica.`,`Castração aberta com bisturi e ligadura.`,`Pinça de Burdizzo.`,`Cauterização química.`,`Castração com tesoura de Serra.`],resposta_correta:`A`,explicacao:`O elastrador com banda elástica é o método mais recomendado para cordeiros até 7 dias de idade, sendo rápido, seguro e com mínima hemorragia. Castração aberta (B) é mais invasiva. Burdizzo (C) é mais usado em bovinos. Cauterização química (D) é menos comum. Tesoura de Serra (E) é mais para bovinos.`},{id:`cga-c-037`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Descola ovina`,dificuldade:`medio`,enunciado:`A descola (remoção do prepúcio) em ovinos é indicada para:`,alternativas:[`Prevenção de acúmulo de urina e sujidade na região prepucial em ovinos de corte.`,`Tratamento de fimose em carneiros adultos.`,`Correção de parafimose aguda.`,`Prevenção de urolitíase em ovinos machos.`,`Melhoria da capacidade reprodutiva.`],resposta_correta:`A`,explicacao:`A descola é indicada para prevenção de acúmulo de urina e sujidade na região prepucial em ovinos de corte, facilitando o abate e melhorando a higiene. Fimose (B), parafimose (C) e urolitíase (D) têm tratamentos específicos. A descola não melhora reprodução (E).`},{id:`cga-c-038`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário 2023`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Herniorrafia ovina`,dificuldade:`dificil`,enunciado:`A herniorrafia umbilical em cabritos está indicada quando:`,alternativas:[`A hérnia é redutível e menor que 2 cm de diâmetro.`,`A hérnia é irredutível com sinais de estrangulamento.`,`O animal apresenta apenas umbigo edemaciado sem hérnia.`,`A hérnia é menor que 1 cm e o animal tem menos de 1 mês.`,`O umbigo está infectado sem protrusão herniária.`],resposta_correta:`B`,explicacao:`A herniorrafia está indicada quando a hérnia é irredutível com sinais de estrangulamento (dor, edema, alteração de cor), constituindo emergência cirúrgica. Hérnias pequenas e redutíveis (A, D) podem ser acompanhadas. Edema sem hérnia (C) e infecção (E) são tratados clinicamente.`},{id:`cga-c-039`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Oftalmologia ovina`,dificuldade:`medio`,enunciado:`O carcinoma de células escamosas (CCE) em ovinos acomete mais frequentemente:`,alternativas:[`A pálpebra e o terceiro olho (membrana nictitante).`,`A córnea e a úvea.`,`A retina e o nervo óptico.`,`A glândula lacrimal.`,`O cristalino.`],resposta_correta:`A`,explicacao:`O carcinoma de células escamosas em ovinos acomete mais frequentemente as pálpebras e a membrana nictitante (terceiro olho), áreas expostas à radiação UV e com epitélio escamoso. Córnea (B), retina (C), glândula lacrimal (D) e cristalino (E) são menos frequentemente acometidos.`},{id:`cga-c-040`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_ovina_caprina`,subtopico:`Desvio de septo nasal caprino`,dificuldade:`medio`,enunciado:`O desvio de septo nasal em cabritos pode causar:`,alternativas:[`Espirro e corrimento nasal mucopurulento.`,`Estridor inspiratório e cianose em repouso.`,`Dispneia expiratória progressiva.`,`Tosse crônica com expectoração.`,`Hemorragia nasal profusa e recorrente.`],resposta_correta:`A`,explicacao:`O desvio de septo nasal em cabritos causa obstrução nasal parcial, levando a espirro, corrimento nasal mucopurulento (por estase de muco) e dificuldade respiratória. Estridor (B) e cianose são mais graves. Dispneia expiratória (C) sugere doença pulmonar. Tosse (D) e hemorragia profusa (E) não são características típicas.`},{id:`cga-c-041`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Castra ovina`,dificuldade:`dificil`,enunciado:`A castra (corte da orelha) em ovinos é uma prática:`,alternativas:[`Proibida pela legislação de bem-estar animal em muitos países, sendo considerada mutilação.`,`Obrigatória para identificação de animais em regime de pastejo extensivo.`,`Recomendada para prevenção de otite externa em ovinos.`,`Necessária para melhorar a termorregulação em climas quentes.`,`Indicada para prevenção de hematomas auriculares em ovinos confinados.`],resposta_correta:`A`,explicacao:`A castra (corte da orelha) é considerada mutilação e é proibida ou restrita em muitas legislações de bem-estar animal. Existem alternativas menos invasivas para identificação (brincos, tatuagem). Não é obrigatória (B), nem recomendada para otite (C), termorregulação (D) ou hematomas (E).`},{id:`cga-c-042`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_ovina_caprina`,subtopico:`Rumenotomia caprina`,dificuldade:`medio`,enunciado:`A rumenotomia em caprinos é indicada para:`,alternativas:[`Remoção de corpos estranhos reticulares e tratamento de timpanismo crônico.`,`Tratamento de diarreia aguda em cabritos.`,`Correção de deslocamento de abomaso.`,`Remoção de cálculos renais.`,`Tratamento de hepatite crônica.`],resposta_correta:`A`,explicacao:`A rumenotomia em caprinos está indicada para remoção de corpos estranhos (plástico, cordas, etc.) que causam timpanismo crônico ou reticulite traumática, e para tratamento de timpanismo crônico refratário. Diarreia (B), DAE (C), cálculos renais (D) e hepatite (E) não requerem rumenotomia.`},{id:`cga-c-043`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`cirurgia_ovina_caprina`,subtopico:`Correção de lábio leporino`,dificuldade:`dificil`,enunciado:`A queiloplastia para correção de lábio leporino (fissura labial) em cabritos é melhor realizada:`,alternativas:[`Entre 2 e 4 semanas de idade, quando o animal já se alimenta bem.`,`No primeiro dia de vida, antes da primeira mamada.`,`Apenas após o desmame, por volta dos 3 meses.`,`Na vida adulta, quando o animal atinge peso adequado.`,`Não é recomendada cirurgia, pois a condição é autolimitante.`],resposta_correta:`A`,explicacao:`A queiloplastia para lábio leporino é idealmente realizada entre 2 e 4 semanas de idade, quando o animal já se alimenta (garantindo recuperação adequada) e os tecidos são mais facilmente manipuláveis. Muito cedo (B) pode comprometer a cicatrização. Desmame (C) é tardio. Adulto (D) é mais difícil. Não é autolimitante (E).`},{id:`cga-c-044`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Amputação de dígito em caprinos`,dificuldade:`medio`,enunciado:`A amputação de dígito em caprinos está indicada para:`,alternativas:[`Pododermatite necrosante (foot rot) crônica refratária ao tratamento clínico.`,`Fratura de falange distal sem desvio.`,`Artrite séptica de articulação interfalângica proximal.`,`Laminite aguda.`,`Crescimento excessivo de casco.`],resposta_correta:`A`,explicacao:`A amputação de dígito está indicada para pododermatite necrosante crônica refratária ao tratamento, onde há destruição extensa dos tecidos digitais. Fraturas sem desvio (B) podem ser tratadas conservadoramente. Artrite séptica (C) pode ser tratada com artrodese. Laminite (D) e crescimento excessivo (E) não requerem amputação.`},{id:`cga-c-045`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Contenção química em ovinos`,dificuldade:`facil`,enunciado:`O fármaco mais utilizado para sedação de ovinos em procedimentos cirúrgicos de campo é:`,alternativas:[`Xilazina.`,`Diazepam.`,`Quetamina.`,`Propofol.`,`Halotano.`],resposta_correta:`A`,explicacao:`A xilazina é o fármaco sedativo mais utilizado para ovinos em procedimentos de campo, proporcionando sedação, analgesia e relaxamento muscular. Diazepam (B) tem efeito sedativo limitado em ruminantes. Quetamina (C) é dissociativa, não sedativa. Propofol (D) e halotano (E) requerem equipamentos específicos.`},{id:`cga-c-046`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Correção de prolapso uterino`,dificuldade:`medio`,enunciado:`Na correção de prolapso uterino em ovelhas, é CORRETO:`,alternativas:[`A redução deve ser realizada com o animal em decúbito esternal, elevando-se os membros pélvicos.`,`A histerectomia é sempre indicada em casos de prolapso uterino.`,`O prolapso uterino em ovelhas é menos grave que em vacas e não requer atenção imediata.`,`A oxitocina é contraindicada no tratamento de prolapso uterino.`,`A sutura vulvar (de Buhner) é obrigatória após toda redução de prolapso.`],resposta_correta:`A`,explicacao:`A redução do prolapso uterino é facilitada com o animal em decúbito esternal com membros pélvicos elevados, reduzindo a pressão intra-abdominal. Histerectomia (B) é indicada apenas em caso de necrose uterina. O prolapso (C) é emergência. Ocitocina (D) é útil para contração uterina. Sutura vulvar (E) é preventiva, não obrigatória.`},{id:`cga-c-047`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_ovina_caprina`,subtopico:`Timpanismo em caprinos`,dificuldade:`facil`,enunciado:`O timpanismo espumoso em caprinos é mais comumente associado a:`,alternativas:[`Consumo excessivo de leguminosas (trevo, alfafa) em pastejo.`,`Infecção por Clostridium perfringens tipo D.`,`Obstrução do esôfago por corpo estranho.`,`Deficiência de cobalto no solo.`,`Parasitismo gastrointestinal severo.`],resposta_correta:`A`,explicacao:`O timpanismo espumoso em caprinos é classicamente associado ao consumo excessivo de leguminosas (trevo, alfafa), que contêm saponinas que estabilizam a espuma no rúmen. C. perfringens (B) causa enterotoxemia. Obstrução (C) causa timpanismo gasoso. Deficiência de cobalto (D) e parasitismo (E) não causam timpanismo.`},{id:`cga-c-048`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Retalho cutâneo em ovinos`,dificuldade:`dificil`,enunciado:`A utilização de retalhos cutâneos em cirurgia de ovinos é indicada para:`,alternativas:[`Cobertura de defeitos cutâneos extensos por trauma ou queimaduras.`,`Tratamento de dermatite por ectoparasitas.`,`Correção de cicatrizes hipertróficas.`,`Tratamento de abscessos subcutâneos.`,`Remoção de tumores cutâneos pequenos.`],resposta_correta:`A`,explicacao:`Retalhos cutâneos são indicados para cobertura de defeitos cutâneos extensos onde a sutura primária não é possível, como em traumas ou queimaduras. Dermatite (B) é tratada clinicamente. Cicatrizes (C) e abscessos (D) têm outros tratamentos. Tumores pequenos (E) são excisados e suturados.`},{id:`cga-c-049`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Ossiotomia de chifre em caprinos`,dificuldade:`medio`,enunciado:`O desacornamento em caprinos adultos (descorna cirúrgica) requer:`,alternativas:[`Anestesia do nervo cornual e hemostasia cuidadosa, pois há artéria cornual.`,`Apenas sedação leve sem anestesia local.`,`Termocauterização como único método de hemostasia.`,`Amputação com serra sem hemostasia complementar.`,`Procedimento ambulatorial sem acompanhamento pós-operatório.`],resposta_correta:`A`,explicacao:`O desacornamento em caprinos adultos requer anestesia do nervo cornual (bloqueio local) e hemostasia cuidadosa devido à artéria cornual, que pode causar hemorragia significativa. Sedação (B) é complementar. Termocauterização (C) é auxiliar. Sem hemostasia (D) é arriscado. Acompanhamento (E) é necessário.`},{id:`cga-c-050`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_ovina_caprina`,subtopico:`Sutura de tendão em ovinos`,dificuldade:`dificil`,enunciado:`A sutura de tendão flexor digital em ovinos após trauma requer:`,alternativas:[`Fixação do membro em flexão por 4-6 semanas pós-operatório.`,`Mobilização imediata para prevenção de aderências.`,`Aplicação de gesso sem mudanças por 12 semanas.`,`Peso livre sobre o membro operado imediatamente.`,`Apenas antibioticoterapia sem imobilização.`],resposta_correta:`A`,explicacao:`Após sutura de tendão, o membro deve ser mantido em flexão (férula ou gesso) por 4-6 semanas para permitir cicatrização do tendão sob tensão mínima. Mobilização imediata (B) causa ruptura. Gesso por 12 semanas (C) é excessivo. Peso livre (D) e apenas antibiótico (E) comprometem a cicatrização.`},{id:`cga-c-051`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_ovina_caprina`,subtopico:`Castração de bodes`,dificuldade:`facil`,enunciado:`A castração de bodes com pinça de Burdizzo é vantajosa porque:`,alternativas:[`Não há abertura de pele, reduzindo o risco de infecção.`,`O método é indolor e não requer contenção.`,`É reversível após 30 dias.`,`Não há risco de complicações.`,`O animal pode retornar ao pastejo imediatamente sem restrição.`],resposta_correta:`A`,explicacao:`A pinça de Burdizzo é vantajosa por ser um método de castração sem incisão (sangue frio), comprimindo o cordão espermático e causando necrose isquêmica, reduzindo o risco de infecção. O método (B) causa dor e requer contenção. Não é reversível (C). Há riscos (D). Restrição (E) é recomendada.`},{id:`cga-c-052`,banca:`ENAV`,ano:2023,prova:`ENAV — Suínos 2023`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Castração suína`,dificuldade:`medio`,enunciado:`Sobre a castração de leitões, é correto afirmar:`,alternativas:[`A castração deve ser realizada preferencialmente nos primeiros 7 dias de vida.`,`A anestesia geral inalatória é obrigatória para castração de leitões.`,`O método com elastrador é o mais recomendado para suínos.`,`A castração química com imunocastração é proibida no Brasil.`,`A castração de leitões não necessita de cuidados pós-operatórios.`],resposta_correta:`A`,explicacao:`A castração de leitões é preferencialmente realizada nos primeiros 7 dias de vida, quando o estresse é menor, a cicatrização é mais rápida e há menor risco de complicações. Anestesia inalatória (B) não é obrigatória. Elastrador (C) não é recomendado para suínos. Imunocastração (D) é permitida. Cuidados (E) são necessários.`},{id:`cga-c-053`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Caudectomia suína`,dificuldade:`facil`,enunciado:`A caudectomia (corte de rabo) em leitões é realizada para:`,alternativas:[`Prevenção de canibalismo e mordida de cauda em sistemas intensivos.`,`Melhoria da eficiência alimentar.`,`Prevenção de doenças respiratórias.`,`Identificação dos animais.`,`Melhoria da qualidade da carne.`],resposta_correta:`A`,explicacao:`A caudectomia é realizada para prevenir o canibalismo e a mordida de cauda, comportamento comum em suínos mantidos em sistemas intensivos de confinamento. Não tem relação com alimentação (B), doenças respiratórias (C), identificação (D) ou qualidade da carne (E).`},{id:`cga-c-054`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Herniorrafia suína`,dificuldade:`dificil`,enunciado:`A hérnia umbilical em leitões é mais frequentemente:`,alternativas:[`Congênita, associada a defeito no fechamento do anel umbilical.`,`Adquirida, por trauma durante o manejo de contenção.`,`Causada por infecção umbilical (onfalite).`,`Secundária a urolitíase.`,`Associada a hérnia diafragmática congênita.`],resposta_correta:`A`,explicacao:`A hérnia umbilical em leitões é geralmente congênita, resultante de defeito no fechamento do anel umbilical durante o desenvolvimento embrionário. Pode ter componente genético. Trauma (B), onfalite (C), urolitíase (D) e hérnia diafragmática (E) não são causas típicas.`},{id:`cga-c-055`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Cesariana suína`,dificuldade:`medio`,enunciado:`A cesariana em porcas está indicada quando:`,alternativas:[`Há distocia por fetos mortos e macerados que não podem ser removidos por via vaginal.`,`O parto dura mais de 4 horas com progressão normal.`,`A porca apresenta apenas 2 leitões vivos.`,`Há contrações fracas sem obstrução mecânica.`,`O intervalo entre nascimentos é de 30 minutos.`],resposta_correta:`A`,explicacao:`A cesariana está indicada em casos de distocia com fetos mortos/macerados que não podem ser removidos por via vaginal, ou quando há obstrução mecânica. Parto de 4 horas (B) pode ser normal. Poucos leitões (C) não indica cesariana. Contrações fracas (D) podem responder a ocitocina. Intervalo de 30 min (E) pode ser normal.`},{id:`cga-c-056`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Descola suína`,dificuldade:`medio`,enunciado:`A descola (remoção do prepúcio) em suínos machos é:`,alternativas:[`Uma prática de bem-estar questionável, sendo proibida em muitos países da UE.`,`Obrigatória para prevenção de urolitíase.`,`Necessária para melhorar a cobertura.`,`Indicada para prevenção de infecções urinárias.`,`Recomendada para aumentar o ganho de peso.`],resposta_correta:`A`,explicacao:`A descola em suínos machos é uma prática de bem-estar questionável, sendo proibida ou restrita em muitos países europeus. Não é obrigatória (B), nem necessária para cobertura (C), nem indicada para infecções (D), nem recomendada para ganho de peso (E).`},{id:`cga-c-057`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_suina`,subtopico:`Amputação de dígito em suínos`,dificuldade:`dificil`,enunciado:`A amputação de dígito em suínos adultos é indicada para:`,alternativas:[`Artrite séptica crônica com destruição articular irreversível.`,`Fratura de falange distal sem desvio.`,`Crescimento excessivo de casco em animais confinados.`,`Pododermatite superficial.`,`Desvio angular em leitões.`],resposta_correta:`A`,explicacao:`A amputação de dígito está indicada em casos de artrite séptica crônica com destruição articular irreversível, quando outros tratamentos falharam. Fraturas (B), crescimento excessivo (C), pododermatite (D) e desvios (E) têm tratamentos menos invasivos.`},{id:`cga-c-058`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Rinoplastia suína`,dificuldade:`medio`,enunciado:`A rinoplastia (correção do focinho) em suínos é indicada para:`,alternativas:[`Correção de atresia ani com fístula retovaginal.`,`Tratamento de rinite atrófica.`,`Correção de desvio de septo nasal.`,`Remoção de pólipos nasais.`,`Tratamento de sinusite crônica.`],resposta_correta:`B`,explicacao:`A rinite atrófica é uma doença respiratória crônica de suínos que causa deformidade do focinho (torção nasal), e a rinoplastia pode ser indicada para correção da deformidade em casos graves. Atresia ani (A) é uma condição retal. Desvio de septo (C), pólipos (D) e sinusite (E) não são indicações típicas.`},{id:`cga-c-059`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_suina`,subtopico:`Esterilização de porcas`,dificuldade:`medio`,enunciado:`A ovariohisterectomia em porcas é mais comumente realizada para:`,alternativas:[`Controle reprodutivo em granjas de terminação.`,`Tratamento de piometra.`,`Prevenção de tumores ovarianos.`,`Melhoria do ganho de peso.`,`Controle de comportamento agressivo.`],resposta_correta:`A`,explicacao:`A ovariohisterectomia em porcas é frequentemente realizada para controle reprodutivo em granjas de terminação (engorda), evitando cio e permitindo melhor manejo. Piometra (B) é rara em suínos. Tumores (C) são incomuns. Ganho de peso (D) e comportamento (E) não são indicações principais.`},{id:`cga-c-060`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`cirurgia_suina`,subtopico:`Urolitíase suína`,dificuldade:`dificil`,enunciado:`A urolitíase obstrutiva em suínos machos é mais comum em:`,alternativas:[`Machos castrados alimentados com ração de alta energia.`,`Machos inteiros em pastejo.`,`Fêmeas em lactação.`,`Leitões neonatos.`,`Machos reprodutores com ração balanceada.`],resposta_correta:`A`,explicacao:`A urolitíase obstrutiva é mais comum em machos castrados devido à menor diâmetro uretral e alimentação com ração de alta energia (rica em minerais). Machos inteiros (B) têm menor risco. Fêmeas (C) têm uretra mais larga. Neonatos (D) e reprodutores balanceados (E) têm menor incidência.`},{id:`cga-c-061`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Polidactilia suína`,dificuldade:`facil`,enunciado:`A polidactilia (dedos extras) em suínos é:`,alternativas:[`Uma anomalia congênita que geralmente não requer tratamento cirúrgico.`,`Uma condição adquirida por trauma.`,`Uma indicação de castração imediata.`,`Uma contraindicação para reprodução.`,`Uma condição infecciosa contagiosa.`],resposta_correta:`A`,explicacao:`A polidactilia é uma anomalia congênita (genética) frequente em suínos, onde há desenvolvimento de dedos extras que geralmente não afetam a locomoção e não requerem correção cirúrgica. Não é adquirida (B), não indica castração (C), não é contraindicação para reprodução (D) e não é infecciosa (E).`},{id:`cga-c-062`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Contenção de suínos`,dificuldade:`facil`,enunciado:`Para contenção de suínos adultos em procedimentos cirúrgicos de campo, o método mais prático é:`,alternativas:[`Contenção mecânica com laço de focinho e cordas em decúbito lateral.`,`Anestesia geral com isoflurano em sala cirúrgica.`,`Contenção química com acepromazina.`,`Uso de gaiola de contenção metálica.`,`Contenção manual por dois auxiliares.`],resposta_correta:`A`,explicacao:`A contenção mecânica com laço de focinho e cordas em decúbito lateral é o método mais prático para cirurgia de campo em suínos adultos. Anestesia inalatória (B) requer infraestrutura. Acepromazina (C) tem efeito variável. Gaiola (D) é para manejo. Dois auxiliares (E) é insuficiente para adultos.`},{id:`cga-c-063`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Ferretamento suíno`,dificuldade:`medio`,enunciado:`O ferretamento (corte dos dentes) em leitões neonatos é:`,alternativas:[`Uma prática controversa de bem-estar, questionada por causar dor e estresse.`,`Obrigatório para prevenção de canibalismo em todas as granjas.`,`Necessário para prevenção de doenças respiratórias.`,`Indicado para melhorar a amamentação.`,`Proibido apenas em sistemas orgânicos.`],resposta_correta:`A`,explicacao:`O ferretamento é uma prática controversa, questionada por causar dor e estresse aos leitões, sendo proibida ou restrita em muitas legislações de bem-estar. Não é obrigatório (B), não previne doenças respiratórias (C), não melhora amamentação (D) e é questionado em qualquer sistema (E).`},{id:`cga-c-064`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_suina`,subtopico:`Ossiotomia de presas em suínos`,dificuldade:`medio`,enunciado:`A ossiotomia (corte dos dentes caninos) em leitões é:`,alternativas:[`Uma prática de manejo para prevenção de lesões nas mamas da porca.`,`Necessária para prevenção de mordida de cauda.`,`Indicada para melhoria da mastigação.`,`Obrigatória em todas as granjas comerciais.`,`Contraindicada por comprometer a amamentação.`],resposta_correta:`A`,explicacao:`A ossiotomia dos caninos em leitões é realizada para prevenção de lesões nas mamas da porca durante a amamentação e de ferimentos nos irmãos de leite. Não previne mordida de cauda (B), não melhora mastigação (C), não é obrigatória (D) e não compromete amamentação (E) quando bem feita.`},{id:`cga-c-065`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Sutura em suínos`,dificuldade:`medio`,enunciado:`Para sutura de pele em suínos, o fio mais recomendado é:`,alternativas:[`Nylon monofilamentar ou polipropileno, por causar menor reação tecidual.`,`Catgut cromado, por ser absorvível.`,`Seda trançada, por ser mais manuseável.`,`Aço inoxidável, por ser mais resistente.`,`Ácido poliglicólico, por ser absorvível rapidamente.`],resposta_correta:`A`,explicacao:`Nylon monofilamentar ou polipropileno são recomendados para sutura de pele em suínos por causar menor reação tecidual e menor aderência bacteriana. Catgut (B) causa reação tecidual. Seda (D) adere bactérias. Aço (D) é difícil de manusear. Ácido poliglicólico (E) é absorvível demais.`},{id:`cga-c-066`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Hérnia escrotal em suínos`,dificuldade:`dificil`,enunciado:`A hérnia escrotal em suínos machos é mais frequentemente:`,alternativas:[`Congênita, associada a defeito no fechamento do canal inguinal.`,`Adquirida por trauma durante monta.`,`Causada por prolapso retal.`,`Secundária a cistite crônica.`,`Associada a criptorquidismo.`],resposta_correta:`A`,explicacao:`A hérnia escrotal em suínos machos é geralmente congênita, resultante de defeito no fechamento do processo vaginal (canal inguinal), permitindo a passagem de alças intestinais para o escroto. Pode ter componente genético. Trauma (B), prolapso (C), cistite (D) e criptorquidismo (E) não são causas típicas.`},{id:`cga-c-067`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_suina`,subtopico:`Cirurgia de prolapso retal em suínos`,dificuldade:`medio`,enunciado:`O prolapso retal em suínos é mais comum em:`,alternativas:[`Porcas em lactação e leitões na fase de creche.`,`Machos reprodutores adultos.`,`Leitões neonatos.`,`Suínos em terminação com alimentação fibrosa.`,`Machos castrados com ração de alta energia.`],resposta_correta:`A`,explicacao:`O prolapso retal em suínos é mais comum em porcas em lactação (por esforço de parto e constipação) e leitões na fase de creche (por tosse crônica e esforço respiratório). Machos reprodutores (B), neonatos (C), terminação (D) e castrados (E) são menos frequentemente acometidos.`},{id:`cga-c-068`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_suina`,subtopico:`Enucleação em suínos`,dificuldade:`medio`,enunciado:`A enucleação (remoção do globo ocular) em suínos está indicada para:`,alternativas:[`Glaucoma refratário ou trauma ocular severo com perda da visão.`,`Conjuntivite bacteriana aguda.`,`Ceratoconjuntivite infecciosa.`,`Uveíte anterior.`,`Catarata congênita.`],resposta_correta:`A`,explicacao:`A enucleação está indicada em casos de glaucoma refratário, trauma ocular severo com perda de visão ou tumores intraoculares, quando o olho é fonte de dor crônica. Conjuntivite (B), ceratoconjuntivite (C), uveíte (D) e catarata (E) são tratados clinicamente.`},{id:`cga-c-069`,banca:`ENAV`,ano:2023,prova:`ENAV — Anestesia GA 2023`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia local em equinos`,dificuldade:`medio`,enunciado:`O bloqueio do nervo palmar lateral no equino anestesia:`,alternativas:[`A região palmar do boleto e parte distal do metacarpo.`,`A região dorsal do boleto e a coroa.`,`A região palmar do carpo.`,`A região axial do membro torácico.`,`A região escapular.`],resposta_correta:`A`,explicacao:`O bloqueio do nervo palmar lateral anestesia a região palmar do boleto (fetlock) e parte distal do metacarpo, sendo útil para localizar dor nessa região. A região dorsal (B) é inervada por nervos diferentes. Carpo (C) é bloqueado por outros nervos. Axial (D) e escapular (E) não são inervados pelo palmar.`},{id:`cga-c-070`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Sedação equina`,dificuldade:`medio`,enunciado:`A associação de detomidina com butorfanol para sedação de equinos:`,alternativas:[`Proporciona sedação profunda e analgesia para procedimentos de curta duração.`,`É contraindicada por interação medicamentosa perigosa.`,`Produz apenas analgesia sem sedação.`,`Requer intubação endotraqueal para administração.`,`Causa hiperexcitação paradoxal em todos os equinos.`],resposta_correta:`A`,explicacao:`A associação de detomidina (alfa-2 agonista) com butorfanol (agonista opioide) é amplamente utilizada para sedação de equinos, proporcionando sedação profunda e analgesia adequada para procedimentos de curta duração como suturas, castração em estação e exames.`},{id:`cga-c-071`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia epidural em bovinos`,dificuldade:`medio`,enunciado:`A anestesia epidural em bovinos é mais comumente realizada no espaço:`,alternativas:[`Sacrococcígeo (entre S1 e Co1).`,`Lombossacral (entre L6 e S1).`,`Toracolombar (entre T13 e L1).`,`Cervical baixo (entre C6 e C7).`,`Intermandibular.`],resposta_correta:`A`,explicacao:`A anestesia epidural em bovinos é classicamente realizada no espaço sacrococcígeo (entre a primeira vértebra sacral e o primeiro segmento coccígeo), onde é mais fácil de acessar e proporciona analgesia perineal. Lombossacral (B) é mais usado em equinos.`},{id:`cga-c-072`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia geral equina`,dificuldade:`dificil`,enunciado:`Na anestesia geral inalatória de equinos, o protocolo mais utilizado é:`,alternativas:[`Indução com quetamina-diazepam e manutenção com isoflurano em oxigênio.`,`Indução com tiopental e manutenção com halotano.`,`Indução com propofol e manutenção com sevoflurano.`,`Indução com ketamina isolada e manutenção com óxido nitroso.`,`Indução com etomidato e manutenção com desflurano.`],resposta_correta:`A`,explicacao:`O protocolo padrão para anestesia geral inalatória em equinos é indução com quetamina-diazepam (ou tiletamina-zolazepam) após sedação com alfa-2 agonista, e manutenção com isoflurano em oxigênio. Halotano (B) é menos usado atualmente. Propofol (C) tem indicações limitadas. Óxido nitroso (D) e desflurano (E) são incomuns em equinos.`},{id:`cga-c-073`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Anestesia 2020`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Contenção química bovina`,dificuldade:`facil`,enunciado:`O fármaco mais utilizado para contenção química de bovinos em procedimentos de campo é:`,alternativas:[`Xilazina.`,`Diazepam.`,`Acepromazina.`,`Propofol.`,`Isoflurano.`],resposta_correta:`A`,explicacao:`A xilazina é o fármaco de escolha para contenção química de bovinos, proporcionando sedação, analgesia e relaxamento muscular. Diazepam (B) tem efeito sedativo limitado em ruminantes. Acepromazina (C) tem efeito variável. Propofol (D) e isoflurano (E) requerem equipamentos específicos.`},{id:`cga-c-074`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`anestesia_ga`,subtopico:`Bloqueio de nervo cornual`,dificuldade:`facil`,enunciado:`O bloqueio do nervo cornual em bovinos anestesia:`,alternativas:[`A região do corno e parte da região temporal.`,`A região frontal e orbital.`,`A região auricular.`,`A região nasal.`,`A região mandibular.`],resposta_correta:`A`,explicacao:`O bloqueio do nervo cornual (ramo do nervo zigomático-temporal) anestesia a região do corno e parte da região temporal, sendo essencial para procedimentos de desacornamento. Frontal (B), auricular (C), nasal (D) e mandibular (E) são inervados por outros nervos.`},{id:`cga-c-075`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia intravenosa total (TIVA) em equinos`,dificuldade:`dificil`,enunciado:`A anestesia intravenosa total (TIVA) em equinos está indicada para:`,alternativas:[`Procedimentos cirúrgicos de curta a média duração quando a anestesia inalatória não está disponível.`,`Apenas para sedação leve em exames clínicos.`,`Procedimentos com duração superior a 4 horas.`,`Cavalos com doença pulmonar grave.`,`Apenas em potros neonatos.`],resposta_correta:`A`,explicacao:`A TIVA está indicada para procedimentos de curta a média duração quando a anestesia inalatória não está disponível ou é impraticável, utilizando protocolos como quetamina-guaifenesina-xilazina. Sedação leve (B) não requer TIVA. Procedimentos longos (C) preferem inalatória.`},{id:`cga-c-076`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`anestesia_ga`,subtopico:`Anestesia local para laparotomia`,dificuldade:`medio`,enunciado:`Para anestesia local de laparotomia em bovinos, a técnica mais utilizada é:`,alternativas:[`Bloqueio em L (inverted L block) ou bloqueio paralombar.`,`Anestesia epidural lombar.`,`Bloqueio de nervo intercostal.`,`Infiltração em leque na linha mediana.`,`Bloqueio do nervo femoral.`],resposta_correta:`A`,explicacao:`O bloqueio em L (inverted L block) ou o bloqueio paralombar são as técnicas mais utilizadas para anestesia de laparotomia em bovinos, proporcionando analgesia adequada da parede abdominal. Epidural (B) não anestesia a parede. Intercostal (C) é para costelas. Infiltração em leque (D) é mais para incisões pequenas. Femoral (E) é para membro pélvico.`},{id:`cga-c-077`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`anestesia_ga`,subtopico:`Riscos anestésicos em equinos`,dificuldade:`dificil`,enunciado:`A principal complicação da anestesia geral em equinos em decúbito dorsal prolongado é:`,alternativas:[`Miopatia por compressão e rabdomiólise.`,`Hipotermia severa.`,`Broncoespasmo.`,`Arritmias cardíacas fatais.`,`Hipoglicemia severa.`],resposta_correta:`A`,explicacao:`A miopatia por compressão é a complicação mais temida em equinos anestesiados em decúbito dorsal prolongado, causada por isquemia muscular e rabdomiólise, podendo levar a sequelas permanentes. Hipotermia (B), broncoespasmo (C), arritmias (D) e hipoglicemia (E) são menos frequentes ou menos específicas.`},{id:`cga-c-078`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia para desacornamento`,dificuldade:`facil`,enunciado:`Para desacornamento em bezerros, a anestesia de escolha é:`,alternativas:[`Bloqueio do nervo cornual com lidocaína.`,`Anestesia geral inalatória.`,`Sedação profunda com xilazina.`,`Anestesia epidural.`,`Injeção intramuscular de quetamina.`],resposta_correta:`A`,explicacao:`O bloqueio do nervo cornual com lidocaína é a anestesia de escolha para desacornamento em bezerros, proporcionando analgesia adequada da região do corno com mínimos efeitos sistêmicos. Anestesia inalatória (B) é desnecessária. Sedação (C) pode ser complementar. Epidural (D) não anestesia a cabeça. Quetamina IM (E) é dissociativa.`},{id:`cga-c-079`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Antagonista de alfa-2 agonistas`,dificuldade:`medio`,enunciado:`O antagonista utilizado para reverter a sedação por xilazina em bovinos é:`,alternativas:[`Atipamezol.`,`Naloxona.`,`Flumazenil.`,`Pralidoxima.`,`Fomepizol.`],resposta_correta:`A`,explicacao:`O atipamezol é o antagonista específico dos receptores alfa-2, utilizado para reverter a sedação causada por xilazina e detomidina. Naloxona (B) antagoniza opioides. Flumazenil (C) antagoniza benzodiazepínicos. Pralidoxima (D) reverte organofosforados. Fomepizol (E) é para intoxicação por etilenoglicol.`},{id:`cga-c-080`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia para castração equina`,dificuldade:`medio`,enunciado:`Para castração de equinos em estação, o protocolo anestésico mais utilizado é:`,alternativas:[`Sedação com detomidina + bloqueio do cordão espermático com lidocaína.`,`Anestesia geral com isoflurano.`,`Apenas contenção mecânica sem anestesia.`,`Anestesia epidural sacrococcígea.`,`Bloqueio do nervo femoral bilateral.`],resposta_correta:`A`,explicacao:`O protocolo padrão para castração em estação é sedação com detomidina (ou romifidina) associada a bloqueio do cordão espermático com lidocaína, proporcionando analgesia local adequada. Anestesia geral (B) é para castração em decúbito. Sem anestesia (C) é inaceitável. Epidural (D) é mais para bovinos. Femoral (E) não anestesia a região.`},{id:`cga-c-081`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`anestesia_ga`,subtopico:`Anestesia para laparoscopia equina`,dificuldade:`dificil`,enunciado:`A anestesia para laparoscopia em equinos requer:`,alternativas:[`Anestesia geral inalatória com ventilação controlada e pneumoperitônio com CO2.`,`Sedação profunda com bloqueio local.`,`Apenas contenção mecânica.`,`Anestesia epidural lombar.`,`Bloqueio de nervos intercostais.`],resposta_correta:`A`,explicacao:`A laparoscopia em equinos requer anestesia geral inalatória com ventilação controlada e pneumoperitônio com CO2 para visualização adequada da cavidade abdominal. Sedação (B) é insuficiente. Contenção (C) não é possível. Epidural (D) e intercostais (E) não anestesiam completamente.`},{id:`cga-c-082`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia em ovinos`,dificuldade:`medio`,enunciado:`Para cirurgia abdominal em ovinos, a anestesia mais utilizada é:`,alternativas:[`Anestesia local infiltrativa associada a sedação com xilazina.`,`Anestesia geral inalatória com isoflurano.`,`Bloqueio de nervo femoral.`,`Anestesia epidural torácica.`,`Apenas contenção mecânica.`],resposta_correta:`A`,explicacao:`A anestesia local infiltrativa associada a sedação com xilazina é o protocolo mais prático e seguro para cirurgia abdominal em ovinos, sendo realizada em campo com equipamentos mínimos. Anestesia inalatória (B) requer infraestrutura. Femoral (C) e epidural torácica (D) não são indicados. Contenção (E) é insuficiente.`},{id:`cga-c-083`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Monitoração anestésica em equinos`,dificuldade:`medio`,enunciado:`Durante anestesia geral em equinos, o parâmetro mais importante para monitorar é:`,alternativas:[`Pressão arterial média (PAM), mantendo acima de 70 mmHg.`,`Temperatura retal.`,`Frequência cardíaca.`,`Concentração de hemoglobina.`,`Glicemia.`],resposta_correta:`A`,explicacao:`A pressão arterial média é o parâmetro mais importante durante anestesia geral em equinos, devendo ser mantida acima de 70 mmHg para garantir perfusão tecidual adequada e prevenir miopatia por compressão. Temperatura (B), frequência cardíaca (C), hemoglobina (D) e glicemia (E) são monitorados, mas PAM é prioritária.`},{id:`cga-c-084`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`anestesia_ga`,subtopico:`Recuperação anestésica equina`,dificuldade:`medio`,enunciado:`A recuperação anestésica de equinos deve ser realizada:`,alternativas:[`Em sala de recuperação acolchoada, com assistência contínua até o animal ficar em estação.`,`Em campo aberto sem proteção.`,`Com o animal amarrado a um poste.`,`Sem monitoramento após extubação.`,`Com uso de estimulação elétrica para acelerar a recuperação.`],resposta_correta:`A`,explicacao:`A recuperação anestésica de equinos deve ser realizada em sala acolchoada com assistência contínua, monitorando sinais vitais e auxiliando o animal a levantar-se com segurança. Campo aberto (B), amarrado (C), sem monitoramento (D) e estimulação (E) são inseguros.`},{id:`cga-c-085`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`anestesia_ga`,subtopico:`Anestesia para contenção de bovinos`,dificuldade:`facil`,enunciado:`A xilazina em bovinos, quando administrada por via intramuscular, produz:`,alternativas:[`Sedação profunda com ataxia e ptose labial em doses de 0,05-0,1 mg/kg.`,`Apenas analgesia sem sedação.`,`Hiperexcitação e tremores musculares.`,`Anestesia geral completa.`,`Apenas relaxamento muscular sem analgesia.`],resposta_correta:`A`,explicacao:`A xilazina em bovinos, na dose de 0,05-0,1 mg/kg IM, produz sedação profunda com ataxia, ptose labial, bradicardia e analgesia. Não produz apenas analgesia (B), hiperexcitação (C), anestesia geral (D) ou apenas relaxamento (E).`},{id:`cga-c-086`,banca:`ENAV`,ano:2023,prova:`ENAV — Ortopedia GA 2023`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Fraturas em equinos`,dificuldade:`dificil`,enunciado:`A fratura de falange proximal em equinos é mais comumente:`,alternativas:[`Fratura sagital medial, frequentemente associada a trauma durante exercício.`,`Fratura cominutiva aberta com exposição óssea.`,`Fratura epifisária em potros.`,`Fratura por estresse em cavalos de corrida.`,`Fratura transversal da diáfise.`],resposta_correta:`A`,explicacao:`A fratura sagital medial da falange proximal é a mais comum em equinos adultos, frequentemente associada a trauma durante exercício ou impacto. Fraturas cominutivas (B) e abertas são menos comuns. Epifisárias (C) são mais em potros. Estresse (D) e transversal (E) são menos frequentes.`},{id:`cga-c-087`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Osteossíntese em bovinos`,dificuldade:`medio`,enunciado:`Julgue o item a seguir sobre osteossíntese em bovinos:`,alternativas:[`VERDADEIRO`,`FALSO`],vf:!0,enunciado_complementar:`A fixação externa com pino-estribo (Kirschner) é o método mais utilizado para fraturas em bovinos jovens, por ser mais simples e apresentar menor custo.`,resposta_correta:`A`,explicacao:`A fixação externa com pino-estribo é amplamente utilizada para fraturas em bovinos jovens, por ser técnica relativamente simples, de menor custo e adequada para ossos longos em animais em crescimento.`},{id:`cga-c-088`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Luxação patelar em equinos`,dificuldade:`medio`,enunciado:`A luxação lateral da patela em equinos é mais comum em:`,alternativas:[`Pôneis e cavalos com conformação angular excessiva do joelho.`,`Cavalos de corrida puro-sangue.`,`Cavalos com hiperextensão do boleto.`,`Potros neonatos com desvio angular.`,`Cavalos com doença navicular.`],resposta_correta:`A`,explicacao:`A luxação lateral da patela é mais comum em pôneis e cavalos com conformação angular excessiva (joelho valgo), que predispor à instabilidade patelar. Puro-sangue (B), hiperextensão (C), neonatos (D) e navicular (E) não são fatores de risco específicos.`},{id:`cga-c-089`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Artroplastia em equinos`,dificuldade:`dificil`,enunciado:`A artroplastia (ressecção de articulação) em equinos está indicada para:`,alternativas:[`Artrite séptica crônica refratária com destruição articular.`,`Osteocondrose em potros.`,`Fraturas articulares simples.`,`Sinovite infecciosa aguda.`,`Laminite crônica.`],resposta_correta:`A`,explicacao:`A artroplastia está indicada para artrite séptica crônica refratária com destruição artilateral irreversível, promovendo fusão articular (artrodese). Osteocondrose (B), fraturas simples (C) e sinovite aguda (D) têm outros tratamentos. Laminite (E) não envolve artroplastia.`},{id:`cga-c-090`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Ortopedia 2020`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Fraturas em bovinos jovens`,dificuldade:`medio`,enunciado:`As fraturas mais comuns em bovinos jovens (bezerros) são:`,alternativas:[`Fraturas de metacarpo e metatarso por trauma durante manejo.`,`Fraturas de pelve por queda.`,`Fraturas de vértebras cervicais.`,`Fraturas de costelas por compressão.`,`Fraturas de mandíbula por mordida.`],resposta_correta:`A`,explicacao:`As fraturas de metacarpo e metatarso são as mais comuns em bovinos jovens, frequentemente causadas por trauma durante manejo (pisoteio, contenção inadequada). Pelve (B), vértebras (C), costelas (D) e mandíbula (E) são menos frequentes.`},{id:`cga-c-091`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`ortopedia_ga`,subtopico:`Amputação de membro em bovinos`,dificuldade:`dificil`,enunciado:`A amputação de membro torácico em bovinos está indicada para:`,alternativas:[`Fratura cominutiva aberta irreparável com infecção grave.`,`Fratura simples de falange distal.`,`Artrite séptica de articulação do boleto.`,`Desvio angular em potros.`,`Laminite crônica.`],resposta_correta:`A`,explicacao:`A amputação de membro está indicada em casos extremos como fratura cominutiva aberta irreparável com infecção grave, quando não há possibilidade de reconstrução ou quando a qualidade de vida é comprometida. Fraturas simples (B), artrite (C), desvios (D) e laminite (E) têm outros tratamentos.`},{id:`cga-c-092`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Doença navicular em equinos`,dificuldade:`medio`,enunciado:`O tratamento cirúrgico da doença navicular (síndrome do navicular) em equinos inclui:`,alternativas:[`Neurectomia palmar digital e desmotomia do ligamento colateral sesamoide.`,`Artrodese da articulação interfalângica distal.`,`Osteossíntese do osso navicular.`,`Amputação da falange distal.`,`Sinovectomia da bainha do tendão digital.`],resposta_correta:`A`,explicacao:`O tratamento cirúrgico da doença navicular inclui neurectomia palmar digital (para analgesia) e desmotomia do ligamento colateral sesamoide (para reduzir tensão). Artrodese (B), osteossíntese (C), amputação (D) e sinovectomia (E) não são indicados para navicular.`},{id:`cga-c-093`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`ortopedia_ga`,subtopico:`Fraturas de costelas em bovinos`,dificuldade:`medio`,enunciado:`As fraturas de costelas em bovinos adultos são mais frequentemente:`,alternativas:[`Causadas por trauma direto (pontapé, queda) e geralmente tratadas conservadoramente.`,`Causadas por osteoporose e requerem osteossíntese.`,`Associadas a pneumotórax e requerem toracotomia imediata.`,`Localizadas na primeira costela.`,`Causadas por neoplasia óssea.`],resposta_correta:`A`,explicacao:`As fraturas de costelas em bovinos adultos são causadas por trauma direto (pontapé de outros animais, queda) e geralmente tratadas conservadoramente com analgesia e restrição de movimento. Osteoporose (B), pneumotórax (C), primeira costela (D) e neoplasia (E) são menos frequentes.`},{id:`cga-c-094`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`ortopedia_ga`,subtopico:`Desvio angular em potros`,dificuldade:`medio`,enunciado:`O tratamento cirúrgico de desvio angular em potros é indicado quando:`,alternativas:[`O desvio não responde ao tratamento conservador (férulas, restrição de exercício) e está progressivo.`,`O potro apresenta qualquer desvio angular ao nascimento.`,`O desvio é menor que 10 graus.`,`O potro tem mais de 6 meses de idade.`,`O desvio é apenas estético, sem comprometimento funcional.`],resposta_correta:`A`,explicacao:`O tratamento cirúrgico (periosteostomia transversal) está indicado quando o desvio angular é progressivo e não responde ao tratamento conservador. Desvios ao nascimento (B) podem ser acompanhados. Desvios menores (C) e apenas estéticos (E) não requerem cirurgia. Idade (D) é relativa.`},{id:`cga-c-095`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Tendinite em equinos`,dificuldade:`dificil`,enunciado:`O tratamento cirúrgico de tendinite do tendão flexor digital superficial em equinos inclui:`,alternativas:[`Tenotomia subcarpiana e desmotomia do ligamento suspensório acessório.`,`Artrodese do boleto.`,`Osteossíntese do metacarpo.`,`Amputação do dígito.`,`Sinovectomia da articulação interfalângica.`],resposta_correta:`A`,explicacao:`A tenotomia subcarpiana do tendão flexor digital superficial e a desmotomia do ligamento suspensório acessório são técnicas cirúrgicas para tratamento de tendinite crônica com contratura. Artrodese (B), osteossíntese (C), amputação (D) e sinovectomia (E) não são indicados para tendinite.`},{id:`cga-c-096`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Fratura de pelve em equinos`,dificuldade:`dificil`,enunciado:`As fraturas de pelve em equinos são mais comumente:`,alternativas:[`Fraturas do ílio (asa do ílio) por trauma, geralmente tratadas conservadoramente.`,`Fraturas do acetábulo por queda, requerendo osteossíntese.`,`Fraturas do púbis por sobrecarga.`,`Fraturas do ísquio por mordida.`,`Fraturas do sacro por compressão.`],resposta_correta:`A`,explicacao:`As fraturas do ílio (asa do ílio) são as mais comuns fraturas pélvicas em equinos, geralmente causadas por trauma e tratadas conservadoramente com repouso. Acetábulo (B), púbis (C), ísquio (D) e sacro (E) são menos frequentes e têm tratamentos específicos.`},{id:`cga-c-097`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Condropatia em bovinos`,dificuldade:`medio`,enunciado:`A osteocondrose em bovinos afeta mais frequentemente:`,alternativas:[`A articulação do jarrete (tibiotársica) e do boleto (metacarpofalângica).`,`A articulação temporomandibular.`,`A articulação escapuloumeral.`,`A articulação atlantoaxial.`,`A articulação esternal.`],resposta_correta:`A`,explicacao:`A osteocondrose em bovinos afeta mais frequentemente a articulação do jarrete (tibiotársica) e do boleto (metacarpofalângica), causando claudicação e redução do desempenho. TMJ (B), escapuloumeral (C), atlantoaxial (D) e esternal (E) são menos acometidos.`},{id:`cga-c-098`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`ortopedia_ga`,subtopico:`Quistos osseos em equinos`,dificuldade:`medio`,enunciado:`Os cistos ósseos subcondrais em equinos são mais frequentemente encontrados em:`,alternativas:[`A articulação do boleto (metacarpofalângica) e do joelho (carpo).`,`A articulação temporomandibular.`,`A articulação interfalângica proximal.`,`A articulação escapuloumeral.`,`A articulação coxofemoral.`],resposta_correta:`A`,explicacao:`Os cistos ósseos subcondrais em equinos são mais frequentemente encontrados na articulação do boleto (metacarpofalângica) e do joelho (carpo), frequentemente associados a osteocondrose. TMJ (B), interfalângica (C), escapuloumeral (D) e coxofemoral (E) são menos acometidos.`},{id:`cga-c-099`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Sesamoidite em equinos`,dificuldade:`facil`,enunciado:`A sesamoidite em equinos é uma inflamação dos ossos sesamoides proximais localizados em:`,alternativas:[`A articulação do boleto (metacarpofalângica), região palmar.`,`A articulação do carpo.`,`A articulação do jarrete.`,`A articulação interfalângica distal.`,`A articulação escapuloumeral.`],resposta_correta:`A`,explicacao:`Os ossos sesamoides proximais estão localizados na região palmar da articulação do boleto (metacarpofalângica), e a sesamoidite é uma condição inflamatória comum em cavalos de esporte. Carpo (B), jarrete (C), interfalângica (D) e escapuloumeral (E) não contêm sesamoides proximais.`},{id:`cga-c-100`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Artrodese em equinos`,dificuldade:`dificil`,enunciado:`A artrodese (fusão cirúrgica de articulação) em equinos está indicada para:`,alternativas:[`Artrite degenerativa crônica do joelho (carpo) refratária ao tratamento clínico.`,`Fratura simples de falange proximal.`,`Osteocondrose em potros.`,`Sinovite aguda.`,`Tendinite crônica.`],resposta_correta:`A`,explicacao:`A artrodese está indicada para artrite degenerativa crônica refratária ao tratamento clínico, promovendo fusão articular e eliminando a fonte de dor. Fraturas simples (B), osteocondrose (C), sinovite (D) e tendinite (E) têm outros tratamentos.`},{id:`cga-c-101`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`ortopedia_ga`,subtopico:`Exame ortopédico equino`,dificuldade:`medio`,enunciado:`No exame ortopédico dinâmico de equinos, a claudicação é avaliada:`,alternativas:[`Com o animal em movimento (trote em linha reta e em círculo), observando a assimetria do movimento.`,`Apenas com o animal em estação.`,`Exclusivamente por palpação dos membros.`,`Por radiografia em movimento.`,`Apenas por ultrassonografia.`],resposta_correta:`A`,explicacao:`O exame ortopédico dinâmico avalia a claudicação com o animal em movimento (trote em linha reta e em círculo), observando a assimetria do movimento, amplitude de passo e apoio. Estação (A) é estática. Palpação (C) é complementar. Radiografia (D) e ultrassonografia (E) são métodos de imagem.`},{id:`cga-c-102`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`ortopedia_ga`,subtopico:`Fratura de escápula em equinos`,dificuldade:`medio`,enunciado:`A fratura da escápula em equinos é mais comum em:`,alternativas:[`Potros durante exercício vigoroso ou trauma durante manejo.`,`Cavalos adultos durante corrida.`,`Equinos com osteoporose.`,`Equinos com doença navicular.`,`Cavalos com luxação escapuloumeral.`],resposta_correta:`A`,explicacao:`A fratura da escápula é mais comum em potros durante exercício vigoroso ou trauma durante manejo, devido à imaturidade óssea. Cavalos adultos (B), osteoporose (C), navicular (D) e luxação (E) não são fatores de risco específicos para fratura de escápula.`},{id:`cga-c-103`,banca:`ENAV`,ano:2023,prova:`ENAV — Cirurgia Abdominal 2023`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Laparotomia exploratória`,dificuldade:`medio`,enunciado:`A laparotomia exploratória em bovinos está indicada para:`,alternativas:[`Investigação de cólica refratária ao tratamento clínico e diagnóstico de obstrução intestinal.`,`Tratamento de timpanismo espumoso agudo.`,`Remoção de corpos estranhos reticulares.`,`Tratamento de diarreia aguda em bezerras.`,`Investigação de febre de origem desconhecida.`],resposta_correta:`A`,explicacao:`A laparotomia exploratória está indicada para investigação de cólica refratária ao tratamento clínico, diagnóstico de obstrução intestinal, volvulo e outras condições abdominais que não respondem ao tratamento clínico. Timpanismo (B), corpos estranhos (C), diarreia (D) e febre (E) têm outros tratamentos.`},{id:`cga-c-104`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Obstrução intestinal em equinos`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre obstrução intestinal em equinos:`,alternativas:[`VERDADEIRO`,`FALSO`],vf:!0,enunciado_complementar:`A obstrução do intestino delgado em equinos é mais grave que a obstrução do cólon grande, devido à rápida progressão de distensão e endotoxemia.`,resposta_correta:`A`,explicacao:`A obstrução do intestino delgado é mais grave devido à rápida distensão proximal ao ponto de obstrução, acúmulo de líquido e endotoxemia, com progressão mais rápida para choque e desordens metabólicas.`},{id:`cga-c-105`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Volvulo em equinos`,dificuldade:`dificil`,enunciado:`O volvulo do cólon grande em equinos é diagnosticado por:`,alternativas:[`Retocção retal, onde se palpam as bandas do cólon torcidas e distendidas.`,`Radiografia abdominal.`,`Ultrassonografia transretal.`,`Apenas sinais clínicos de cólica.`,`Endoscopia gastrointestinal.`],resposta_correta:`A`,explicacao:`O diagnóstico de volvulo do cólon grande é feito por retocção retal, onde se palpam as bandas do cólon torcidas e distendidas. Radiografia (B) tem limitações em adultos. Ultrassonografia (C) é complementar. Sinais clínicos (D) são inespecíficos. Endoscopia (E) não alcança o cólon.`},{id:`cga-c-106`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Hérnia diafragmática em equinos`,dificuldade:`dificil`,enunciado:`A hérnia diafragmática em equinos é:`,alternativas:[`Uma condição rara, geralmente traumática, com prognóstico reservado.`,`Uma condição comum em potros neonatos.`,`Uma condição congênita frequente em cavalos de corrida.`,`Uma condição autolimitante que não requer tratamento.`,`Uma condição que ocorre apenas em equinos idosos.`],resposta_correta:`A`,explicacao:`A hérnia diafragmática em equinos é rara, geralmente causada por trauma (pontapé, queda), e apresenta prognóstico reservado devido à complexidade da correção cirúrgica e comprometimento respiratório. Não é comum (B), congênita (C), autolimitante (D) ou exclusiva de idosos (E).`},{id:`cga-c-107`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Sutura intestinal em equinos`,dificuldade:`medio`,enunciado:`Para sutura intestinal em equinos, o fio mais recomendado é:`,alternativas:[`Ácido poliglicólico (Dexon) ou poliglactina 910 (Vicryl), por ser absorvível e ter boa resistência.`,`Seda trançada, por ser mais manuseável.`,`Nylon monofilamentar, por ser inerte.`,`Catgut simples, por ser rapidamente absorvido.`,`Aço inoxidável, por ser mais resistente.`],resposta_correta:`A`,explicacao:`Ácido poliglicólico (Dexon) ou poliglactina 910 (Vicryl) são recomendados para sutura intestinal por serem absorvíveis, manterem resistência adequada durante a cicatrização e causarem menor reação tecidual. Seda (B) adere bactérias. Nylon (C) não é absorvível. Catgut (D) é reativo. Aço (E) é difícil de manusear.`},{id:`cga-c-108`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_abdominal_ga`,subtopico:`Descompressão gástrica equina`,dificuldade:`medio`,enunciado:`A descompressão gástrica por sonda nasogástrica em equinos é:`,alternativas:[`Medida terapêutica essencial em cólicas com distensão gástrica, prevenindo ruptura gástrica.`,`Procedimento diagnóstico apenas, sem valor terapêutico.`,`Contraindicada em equinos com cólica.`,`Indicada apenas para administração de medicamentos.`,`Realizada apenas em ambiente hospitalar.`],resposta_correta:`A`,explicacao:`A sonda nasogástrica é essencial para descompressão gástrica em equinos com distensão, prevenindo ruptura gástrica (uma complicação fatal). É terapêutica (B), não contraindicada (C), não apenas para medicamentos (D) e pode ser realizada em campo (E).`},{id:`cga-c-109`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Intussuscepção em bovinos`,dificuldade:`dificil`,enunciado:`A intussuscepção (invaginação intestinal) em bovinos é mais comum em:`,alternativas:[`Bezerros com diarreia crônica e parasitismo gastrointestinal.`,`Bovinos adultos com timpanismo.`,`Vacas em lactação com cetose.`,`Bois em terminação com obesidade.`,`Touros reprodutores com hérnia inguinal.`],resposta_correta:`A`,explicacao:`A intussuscepção em bovinos é mais comum em bezerros com diarreia crônica e parasitismo gastrointestinal, que causam alterações no peristaltismo e predisposição à invaginação. Timpanismo (B), cetose (C), obesidade (D) e hérnia (E) não são fatores de risco específicos.`},{id:`cga-c-110`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_abdominal_ga`,subtopico:`Cólica em equinos`,dificuldade:`medio`,enunciado:`Os sinais clínicos de cólica em equinos que indicam necessidade de intervenção cirúrgica incluem:`,alternativas:[`Dor refratária a analgesia, distensão abdominal progressiva e alterações no retocção retal.`,`Dor leve que responde a analgesia.`,`Apenas diminuição do apetite.`,`Apenas fezes ressecadas.`,`Apenas taquicardia leve.`],resposta_correta:`A`,explicacao:`Os indicadores de intervenção cirúrgica incluem dor refratária a analgesia, distensão abdominal progressiva, alterações retais sugestivas de obstrução/deslocamento e deterioração dos sinais vitais. Dor leve (B), apetite (C), fezes (D) e taquicardia leve (E) podem ser acompanhados clinicamente.`},{id:`cga-c-111`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`cirurgia_abdominal_ga`,subtopico:`Enterotomia em equinos`,dificuldade:`dificil`,enunciado:`A enterotomia (incisão intestinal) em equinos é realizada para:`,alternativas:[`Remoção de enterólitos, cálculos e corpos estranhos impactados no intestino.`,`Tratamento de diarreia crônica.`,`Correção de prolapso retal.`,`Remoção de tumores intestinais.`,`Tratamento de úlceras gástricas.`],resposta_correta:`A`,explicacao:`A enterotomia é realizada para remoção de enterólitos, cálculos e corpos estranhos impactados no intestino, que não podem ser removidos por descompressão ou manipulação manual. Diarreia (B), prolapso (C), tumores (D) e úlceras (E) têm outros tratamentos.`},{id:`cga-c-112`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Ressecção intestinal em equinos`,dificuldade:`dificil`,enunciado:`A ressecção intestinal (enterectomia) em equinos está indicada quando:`,alternativas:[`Há necrose intestinal extensa por volvulo ou estrangulamento, com viabilidade comprometida.`,`Apenas para remoção de enterólitos.`,`Em todos os casos de obstrução intestinal.`,`Quando há diarreia crônica.`,`Para tratamento de úlceras gástricas.`],resposta_correta:`A`,explicacao:`A ressecção intestinal está indicada quando há necrose intestinal extensa por volvulo, estrangulamento ou intussuscepção, com viabilidade comprometida. Enterólitos (B) requerem enterotomia. Nem toda obstrução (C) requer ressecção. Diarreia (D) e úlceras (E) não são indicações.`},{id:`cga-c-113`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Anastomose intestinal`,dificuldade:`medio`,enunciado:`A técnica de anastomose mais utilizada para intestino delgado em equinos é:`,alternativas:[`Anastomose término-terminal com sutura em duas camadas.`,`Anastomose término-lateral.`,`Anastomose látero-lateral.`,`Anastomose com grampeador cirúrgico.`,`Anastomose com cola de fibrina.`],resposta_correta:`A`,explicacao:`A anastomose término-terminal com sutura em duas camadas (seromuscular e mucosa-submucosa) é a técnica mais utilizada para intestino delgado em equinos, proporcionando boa vedação e vascularização. Término-lateral (B) e látero-lateral (C) têm indicações específicas. Grampeador (D) e cola (E) são menos utilizados em equinos.`},{id:`cga-c-114`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Peritonite em equinos`,dificuldade:`dificil`,enunciado:`A peritonite em equinos é mais comumente:`,alternativas:[`Secundária a perfuração intestinal por úlcera gástrica ou enterólito.`,`Primária, sem causa identificável.`,`Causada por infecção hematogênica.`,`Associada a trauma torácico.`,`Causada por parasitismo pulmonar.`],resposta_correta:`A`,explicacao:`A peritonite em equinos é mais comumente secundária a perfuração intestinal (por úlcera gástrica, enterólito, volvulo), com contaminação da cavidade peritoneal. Não é primária (A), hematogênica (C), torácica (D) ou pulmonar (E).`},{id:`cga-c-115`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_abdominal_ga`,subtopico:`Adesões peritoneais`,dificuldade:`medio`,enunciado:`As aderências peritoneais pós-cirúrgicas em equinos são:`,alternativas:[`Complicação comum que pode causar recorrência de cólica.`,`Raramente observadas após cirurgia abdominal.`,`Sempre assintomáticas.`,`Prevenidas apenas com antibioticoterapia.`,`Tratadas exclusivamente com anti-inflamatórios.`],resposta_correta:`A`,explicacao:`As aderências peritoneais são complicação comum após cirurgia abdominal em equinos, podendo causar obstrução intestinal e recorrência de cólica. São frequentes (B), podem ser sintomáticas (C), antibioticoterapia (D) não previne e anti-inflamatórios (E) não tratam.`},{id:`cga-c-116`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Fístula umbilical em bovinos`,dificuldade:`medio`,enunciado:`A fístula umbilical (onfaloarterite) em bezerros é tratada por:`,alternativas:[`Resecção cirúrgica do coto umbilical infectado e ligadura dos vasos.`,`Apenas antibioticoterapia sistêmica.`,`Drenagem do abscesso sem ressecção.`,`Cauterização química.`,`Observação espontânea.`],resposta_correta:`A`,explicacao:`O tratamento da fístula umbilical é cirúrgico, com ressecção do coto umbilical infectado e ligadura dos vasos umbilicais (artéria e veia). Antibioticoterapia (B) é complementar. Drenagem (C) e cauterização (D) são insuficientes. Observação (E) permite progressão.`},{id:`cga-c-117`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Cecocecostomia em equinos`,dificuldade:`dificil`,enunciado:`A cecocecostomia em equinos está indicada para:`,alternativas:[`Tratamento de volvulo cecal com viabilidade intestinal preservada.`,`Remoção de enterólitos do ceco.`,`Tratamento de úlceras cecais.`,`Descompressão do ceco em timpanismo.`,`Ressecção de tumor cecal.`],resposta_correta:`A`,explicacao:`A cecocecostomia (anastomose do ceco ao ceco após desrotação) está indicada para tratamento de volvulo cecal com viabilidade intestinal preservada. Enterólitos (B), úlceras (C), timpanismo (D) e tumores (E) têm outros tratamentos.`},{id:`cga-c-118`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_abdominal_ga`,subtopico:`Flutuação intestinal em bovinos`,dificuldade:`medio`,enunciado:`A flutuação intestinal (omentopexia) em bovinos é utilizada para:`,alternativas:[`Fixação do abomaso à parede abdominal no tratamento de DAE.`,`Tratamento de volvulo cecal.`,`Correção de hérnia inguinal.`,`Tratamento de intussuscepção.`,`Descompressão do rúmen.`],resposta_correta:`A`,explicacao:`A omentopexia é utilizada para fixação do abomaso à parede abdominal ventral direita no tratamento de DAE, prevenindo recorrência. Volvulo (B), hérnia (C), intussuscepção (D) e descompressão (E) não envolvem omentopexia.`},{id:`cga-c-119`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_abdominal_ga`,subtopico:`Toracotomia em bovinos`,dificuldade:`medio`,enunciado:`A laparotomia para correção de DAE em bovinos é mais frequentemente realizada:`,alternativas:[`Pelo flanco direito, com o animal em estação.`,`Pelo flanco esquerdo, com o animal em decúbito.`,`Por linha mediana ventral, com o animal em decúbito dorsal.`,`Por acesso subcostal bilateral.`,`Por laparoscopia.`],resposta_correta:`A`,explicacao:`A laparotomia para correção de DAE é classicamente realizada pelo flanco direito, com o animal em estação, permitindo acesso ao abomaso para descompressão e fixação. Flanco esquerdo (B) é para rumenotomia. Linha mediana (C) é mais para equinos.`},{id:`cga-c-120`,banca:`ENAV`,ano:2023,prova:`ENAV — Cirurgia Torácica 2023`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Toracotomia em equinos`,dificuldade:`medio`,enunciado:`A toracotomia intercostal em equinos está indicada para:`,alternativas:[`Remoção de neoplasias pulmonares, drenagem de empiema e biópsia pulmonar.`,`Tratamento de bronquite crônica.`,`Remoção de corpos estranhos brônquicos.`,`Tratamento de asma equina.`,`Drenagem de abcesso subcutâneo torácico.`],resposta_correta:`A`,explicacao:`A toracotomia intercostal está indicada para remoção de neoplasias pulmonares, drenagem de empiema (coleção pleural infectada), biópsia pulmonar e outras condições que requerem acesso direto à cavidade torácica. Bronquite (B), asma (D) e abscessos (E) são tratados clinicamente.`},{id:`cga-c-121`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Pneumotórax em equinos`,dificuldade:`medio`,enunciado:`O pneumotórax em equinos é mais comumente:`,alternativas:[`Traumático, causado por perfuração da parede torácica ou ruptura pulmonar.`,`Espontâneo, sem causa identificável.`,`Causado por pneumonia bacteriana.`,`Associado a doença cardíaca congênita.`,`Causado por parasitismo pulmonar.`],resposta_correta:`A`,explicacao:`O pneumotórax em equinos é mais comumente traumático, causado por perfuração da parede torácica (cerca, ferramentas) ou ruptura pulmonar por trauma. Não é espontâneo (B), causado por pneumonia (C), doença cardíaca (D) ou parasitismo (E).`},{id:`cga-c-122`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Derrame pleural em bovinos`,dificuldade:`medio`,enunciado:`O derrame pleural em bovinos é mais frequentemente:`,alternativas:[`Secundário a pleuroneumonia por corpo estranho reticular.`,`Primário, sem causa identificável.`,`Causado por trauma torácico.`,`Associado a insuficiência cardíaca.`,`Causado por parasitismo pulmonar.`],resposta_correta:`A`,explicacao:`O derrame pleural em bovinos é mais frequentemente secundário a pleuroneumonia por corpo estranho reticular (geralmente arame que migra do retículo), uma condição comum em bovinos. Não é primário (B), traumático (C), cardíaco (D) ou parasitário (E).`},{id:`cga-c-123`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Toracocentese em equinos`,dificuldade:`medio`,enunciado:`A toracocentese em equinos é realizada para:`,alternativas:[`Diagnóstico e drenagem de derrame pleural (líquido pleural).`,`Administração de medicamentos intrapleurais.`,`Descompressão pulmonar.`,`Biópsia de pulmão.`,`Todos os itens anteriores.`],resposta_correta:`A`,explicacao:`A toracocentese é realizada primariamente para diagnóstico (coleta de líquido pleural para análise) e drenagem terapêutica de derrame pleural. Medicamentos intrapleurais (B) e biópsia (D) são procedimentos complementares que podem ser realizados, mas a indicação primária é a drenagem diagnóstica/terapêutica.`},{id:`cga-c-124`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Fraturas de costelas em bovinos`,dificuldade:`medio`,enunciado:`As fraturas de costelas em bovinos podem causar:`,alternativas:[`Pneumotórax, hemotórax e laceração pulmonar.`,`Apenas dor local sem complicações.`,`Apenas hemorragia externa.`,`Apenas infecção superficial.`,`Apenas deformidade estética.`],resposta_correta:`A`,explicacao:`As fraturas de costelas podem causar complicações graves como pneumotórax (ar na cavidade pleural), hemotórax (sangue na cavidade pleural) e laceração pulmonar, dependendo da gravidade e localização da fratura. Não são apenas dor (B), hemorragia (C), infecção (D) ou deformidade (E).`},{id:`cga-c-125`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_toracica_ga`,subtopico:`Drenagem torácica em equinos`,dificuldade:`medio`,enunciado:`A drenagem torácica em equinos é realizada:`,alternativas:[`Com dreno de Penrose ou dreno torácico fechado, no espaço intercostal adequado.`,`Com sonda nasogástrica inserida na cavidade pleural.`,`Apenas por aspiração com agulha.`,`Com dreno abdominal.`,`Apenas por toracoscopia.`],resposta_correta:`A`,explicacao:`A drenagem torácica em equinos é realizada com dreno de Penrose (aberto) ou dreno torácico fechado, inserido no espaço intercostal adequado (geralmente 6º-8º). Sonda nasogástrica (B) não é adequada. Aspiração (C) é complementar. Dreno abdominal (D) é diferente. Toracoscopia (E) é diagnóstica.`},{id:`cga-c-126`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Empiema pleural em equinos`,dificuldade:`dificil`,enunciado:`O empiema pleural (coleção de pus na cavidade pleural) em equinos é mais comumente:`,alternativas:[`Secundário a pneumonia bacteriana, pleurite ou perfuração esofágica.`,`Primário, sem infecção.`,`Causado por trauma torácico sem infecção.`,`Associado a insuficiência cardíaca.`,`Causado por parasitismo intestinal.`],resposta_correta:`A`,explicacao:`O empiema pleural em equinos é secundário a pneumonia bacteriana, pleurite ou perfuração esofágica, com contaminação da cavidade pleural. Não é primário (B), traumático sem infecção (C), cardíaco (D) ou intestinal (E).`},{id:`cga-c-127`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_toracica_ga`,subtopico:`Pericardite traumática em bovinos`,dificuldade:`dificil`,enunciado:`A pericardite traumática em bovinos é causada por:`,alternativas:[`Migração de corpo estranho reticular (geralmente arame) que perfura o diafragma e pericárdio.`,`Infecção viral do miocárdio.`,`Trauma torácico direto (pontapé).`,`Parasitismo cardíaco.`,`Infecção bacteriana primária do pericárdio.`],resposta_correta:`A`,explicacao:`A pericardite traumática em bovinos é classicamente causada por migração de corpo estranho reticular (geralmente arame ingerido com alimento) que perfura o diafragma e atinge o pericárdio. Não é viral (B), traumática direta (C), parasitária (D) ou primária (E).`},{id:`cga-c-128`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`cirurgia_toracica_ga`,subtopico:`Toracoscopia em equinos`,dificuldade:`medio`,enunciado:`A toracoscopia em equinos é utilizada para:`,alternativas:[`Diagnóstico de doenças pleurais e pulmonares, biópsia e drenagem de coleções.`,`Apenas para remoção de corpos estranhos esofágicos.`,`Tratamento de arritmias cardíacas.`,`Remoção de tumores cardíacos.`,`Apenas para avaliação da função pulmonar.`],resposta_correta:`A`,explicacao:`A toracoscopia é utilizada para diagnóstico de doenças pleurais e pulmonares, biópsia guiada e drenagem de coleções, sendo menos invasiva que a toracotomia. Não é para esôfago (B), arritmias (C), tumores cardíacos (D) ou função pulmonar (E).`},{id:`cga-c-129`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Laceração pulmonar em equinos`,dificuldade:`dificil`,enunciado:`A laceração pulmonar em equinos pode causar:`,alternativas:[`Pneumotórax, hemotórax e insuficiência respiratória.`,`Apenas tosse.`,`Apenas febre.`,`Apenas dor torácica.`,`Apenas taquicardia.`],resposta_correta:`A`,explicacao:`A laceração pulmonar pode causar pneumotórax (vazamento de ar), hemotórax (sangramento) e insuficiência respiratória, constituindo emergência. Tosse (B), febre (C), dor (D) e taquicardia (E) são sinais inespecíficos que podem estar presentes, mas as complicações são mais graves.`},{id:`cga-c-130`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Hérnia diafragmática em bovinos`,dificuldade:`dificil`,enunciado:`A hérnia diafragmática em bovinos é mais frequentemente:`,alternativas:[`Congênita, associada a defeito no fechamento do septo transverso.`,`Adquirida por trauma durante o parto.`,`Causada por timpanismo crônico.`,`Associada a prolapso retal.`,`Causada por parasitismo pulmonar.`],resposta_correta:`A`,explicacao:`A hérnia diafragmática em bovinos é mais frequentemente congênita, resultante de defeito no fechamento do septo transverso durante o desenvolvimento embrionário. Trauma (B), timpanismo (C), prolapso (D) e parasitismo (E) não são causas típicas.`},{id:`cga-c-131`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Sutura torácica`,dificuldade:`medio`,enunciado:`Para fechamento de toracotomia em equinos, é essencial:`,alternativas:[`Sutura hermética da pleura e músculos intercostais, com drenagem pleural temporária.`,`Apenas fechamento da pele.`,`Deixar a toracotomia aberta para cicatrização por segunda intenção.`,`Usar apenas pontos de pele sem fechar camadas profundas.`,`Aplicar bandagem compressiva sem sutura.`],resposta_correta:`A`,explicacao:`O fechamento de toracotomia requer sutura hermética da pleura e músculos intercostais para evitar pneumotórax, com drenagem pleural temporária para evacuação de ar e líquido. Apenas pele (B), aberta (C), sem camadas (D) e bandagem (E) são inadequados.`},{id:`cga-c-132`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_toracica_ga`,subtopico:`Drenagem torácica em bovinos`,dificuldade:`medio`,enunciado:`A drenagem torácica em bovinos com pleuroneumonia é:`,alternativas:[`Essencial para remoção de líquido pleural e melhoria da função respiratória.`,`Contraindicada por risco de infecção.`,`Indicada apenas em neonatos.`,`Necessária apenas quando há febre.`,`Substituída por antibioticoterapia isolada.`],resposta_correta:`A`,explicacao:`A drenagem torácica é essencial em bovinos com pleuroneumonia para remoção de líquido pleural (pus, exsudato), promovendo melhoria da função respiratória e facilitando a antibioticoterapia. Não é contraindicada (B), neonatal (C), apenas com febre (D) nem substituível (E).`},{id:`cga-c-133`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Tumor pulmonar em equinos`,dificuldade:`dificil`,enunciado:`Os tumores pulmonares mais comuns em equinos são:`,alternativas:[`Sarcoma e carcinoma metastático, frequentemente de origem em outros órgãos.`,`Carcinoma broncogênico primário.`,`Adenoma pulmonar.`,`Lipoma pulmonar.`,`Hemangioma pulmonar.`],resposta_correta:`A`,explicacao:`Os tumores pulmonares em equinos são mais frequentemente metastáticos (sarcoma, carcinoma), originários de outros órgãos. Carcinoma broncogênico primário (B) é raro. Adenoma (C), lipoma (D) e hemangioma (E) são muito raros.`},{id:`cga-c-134`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Ruptura esofágica em equinos`,dificuldade:`dificil`,enunciado:`A ruptura esofágica em equinos pode causar:`,alternativas:[`Pneumomediastino, pneumotórax e mediastinite.`,`Apenas disfagia.`,`Apenas regurgitação.`,`Apenas dor cervical.`,`Apenas febre.`],resposta_correta:`A`,explicacao:`A ruptura esofágica pode causar pneumomediastino (ar no mediastino), pneumotórax (ar na cavidade pleural) e mediastinite (infecção do mediastino), condições graves. Disfagia (B), regurgitação (C), dor (D) e febre (E) são sinais inespecíficos.`},{id:`cga-c-135`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_toracica_ga`,subtopico:`Cirurgia toracoscópica em equinos`,dificuldade:`medio`,enunciado:`A cirurgia toracoscópica em equinos é:`,alternativas:[`Minimamente invasiva, permitindo visualização direta da cavidade torácica com menor morbidade.`,`Mais invasiva que a toracotomia aberta.`,`Indicada apenas para diagnóstico, não para tratamento.`,`Contraindicada em equinos adultos.`,`Realizada apenas em potros.`],resposta_correta:`A`,explicacao:`A toracoscopia é minimamente invasiva, permitindo visualização direta da cavidade torácica com menor morbidade, menos dor pós-operatória e recuperação mais rápida que a toracotomia aberta. É menos invasiva (B), terapêutica (C), indicada em adultos (D) e potros (E).`},{id:`cga-c-136`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_toracica_ga`,subtopico:`Abscesso pulmonar em bovinos`,dificuldade:`medio`,enunciado:`O abscesso pulmonar em bovinos é mais comumente:`,alternativas:[`Secundário a pneumonia aspirativa ou pleuroneumonia por corpo estranho.`,`Primário, sem causa identificável.`,`Causado por trauma torácico.`,`Associado a insuficiência cardíaca.`,`Causado por parasitismo gastrointestinal.`],resposta_correta:`A`,explicacao:`O abscesso pulmonar em bovinos é mais comumente secundário a pneumonia aspirativa (por regurgitação) ou pleuroneumonia por corpo estranho reticular. Não é primário (B), traumático (C), cardíaco (D) ou gastrointestinal (E).`},{id:`cga-c-137`,banca:`ENAV`,ano:2023,prova:`ENAV — Cirurgia Tegumentar 2023`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Suturas em equinos`,dificuldade:`medio`,enunciado:`Para sutura de pele em equinos, a técnica mais recomendada é:`,alternativas:[`Sutura de Donati modificada (colchoada horizontal) para fechamento de incisões cirúrgicas.`,`Sutura contínua simples.`,`Sutura em pontos separados simples com fio de catgut.`,`Agrafagem com grampos metálicos.`,`Sutura intradérmica contínua.`],resposta_correta:`A`,explicacao:`A sutura de Donati modificada (colchoada horizontal) é recomendada para fechamento de pele em equinos por proporcionar boa eversão das bordas, resistência e redução de tensão. Contínua simples (B) pode isquemiar. Catgut (C) é reativo. Agrafagem (D) e intradérmica (E) são menos comuns.`},{id:`cga-c-138`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Enxertos cutâneos em equinos`,dificuldade:`dificil`,enunciado:`Os enxertos cutâneos em equinos são:`,alternativas:[`Indicados para cobertura de defeitos cutâneos extensos por trauma ou queimaduras.`,`Contraindicados por rejeição imunológica.`,`Utilizados apenas em potros.`,`Indicados apenas para tumores cutâneos.`,`Substituídos por antibioticoterapia.`],resposta_correta:`A`,explicacao:`Os enxertos cutâneos são indicados para cobertura de defeitos cutâneos extensos onde a sutura primária não é possível, como traumas, queimaduras e ressecções tumorais. Não há rejeição significativa (B), não são apenas para potros (C), não apenas para tumores (D) e não são substituíveis (E).`},{id:`cga-c-139`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Retalhos cutâneos em bovinos`,dificuldade:`medio`,enunciado:`Os retalhos cutâneos em bovinos são:`,alternativas:[`Utilizados para cobertura de defeitos cutâneos onde a tensão impede sutura primária.`,`Contraindicados por falta de vascularização.`,`Indicados apenas para animais de exposição.`,`Substituídos por enxertos livres.`,`Indicados apenas para membros.`],resposta_correta:`A`,explicacao:`Os retalhos cutâneos (pediculados) são utilizados quando há tensão excessiva que impede a sutura primária, mantendo vascularização própria. Não são contraindicados (B), não apenas para exposição (C), não substituídos por enxertos (D) e não apenas para membros (E).`},{id:`cga-c-140`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Queimaduras em equinos`,dificuldade:`medio`,enunciado:`O tratamento cirúrgico de queimaduras em equinos inclui:`,alternativas:[`Desbridamento de tecido necrótico e cobertura com enxerto ou retalho cutâneo.`,`Apenas antibioticoterapia sistêmica.`,`Apenas aplicação de pomadas tópicas.`,`Observação sem intervenção.`,`Amputação do membro afetado.`],resposta_correta:`A`,explicacao:`O tratamento cirúrgico de queimaduras envolve desbridamento de tecido necrótico e cobertura da ferida com enxerto cutâneo ou retalho, dependendo da extensão. Antibioticoterapia (B) é complementar. Pomadas (C) são para queimaduras superficiais. Observação (D) é inadequada. Amputação (E) é último recurso.`},{id:`cga-c-141`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Granulação exuberante em equinos`,dificuldade:`medio`,enunciado:`A granulação exuberante (proud flesh) em equinos é:`,alternativas:[`Proliferação excessiva de tecido de granulação que impede a epitelização.`,`Infecção bacteriana da ferida.`,`Tumor cutâneo benigno.`,`Reação alérgica a fio de sutura.`,`Cicatrização normal.`],resposta_correta:`A`,explicacao:`A granulação exuberante é proliferação excessiva de tecido de granulação que ultrapassa os bordos da ferida, impedindo a epitelização e requerendo desbridamento. Não é infecção (B), tumor (C), reação alérgica (D) nem normal (E).`},{id:`cga-c-142`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`cirurgia_tegumentar_ga`,subtopico:`Sutura em bovinos`,dificuldade:`facil`,enunciado:`O fio de sutura mais utilizado para pele em bovinos é:`,alternativas:[`Nylon monofilamentar ou polipropileno.`,`Catgut cromado.`,`Seda trançada.`,`Ácido poliglicólico.`,`Aço inoxidável.`],resposta_correta:`A`,explicacao:`Nylon monofilamentar ou polipropileno são os fios mais utilizados para sutura de pele em bovinos por serem inertes, de fácil manuseio e causarem menor reação tecidual. Catgut (B) é reativo. Seda (C) adere bactérias. Ácido poliglicólico (D) é absorvível. Aço (E) é difícil de manusear.`},{id:`cga-c-143`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Cicatrização em equinos`,dificuldade:`medio`,enunciado:`A cicatrização de feridas em equinos é:`,alternativas:[`Lenta, com tendência a formação de granulação exuberante, especialmente nos membros.`,`Rápida, sem complicações.`,`Idêntica à de cães.`,`Apenas por primeira intenção.`,`Apenas por segunda intenção.`],resposta_correta:`A`,explicacao:`A cicatrização em equinos é lenta, com tendência a formação de granulação exuberante (proud flesh), especialmente nos membros onde há pouca pele e tensão. Não é rápida (B), idêntica à de cães (C), nem exclusivamente por primeira (D) ou segunda intenção (E).`},{id:`cga-c-144`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`cirurgia_tegumentar_ga`,subtopico:`Desbridamento de feridas`,dificuldade:`medio`,enunciado:`O desbridamento cirúrgico de feridas em equinos é:`,alternativas:[`Remoção de tecido desvitalizado, corpos estranhos e debris para promover cicatrização.`,`Apenas lavagem com soro fisiológico.`,`Aplicação de antibioticoterapia tópica.`,`Cobertura com bandagem oclusiva.`,`Sutura primária imediata.`],resposta_correta:`A`,explicacao:`O desbridamento cirúrgico envolve remoção de tecido desvitalizado, corpos estranhos e debris, promovendo condições adequadas para cicatrização. Lavagem (B), antibióticos (C) e bandagem (D) são complementares. Sutura imediata (E) pode não ser possível.`},{id:`cga-c-145`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`cirurgia_tegumentar_ga`,subtopico:`Tumores cutâneos em equinos`,dificuldade:`dificil`,enunciado:`O tumor cutâneo mais comum em equinos é:`,alternativas:[`Sarcóide equino, tumor de origem fibroblástica associado a papilomavírus.`,`Carcinoma de células escamosas.`,`Melanoma.`,`Mastocitoma.`,`Lipoma.`],resposta_correta:`A`,explicacao:`O sarcóide equino é o tumor cutâneo mais comum em equinos, de origem fibroblástica associado a papilomavírus bovino (BPV). Carcinoma (B), melanoma (C), mastocitoma (D) e lipoma (E) são menos frequentes.`},{id:`cga-c-146`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Tratamento de sarcóide equino`,dificuldade:`dificil`,enunciado:`O tratamento cirúrgico do sarcóide equino inclui:`,alternativas:[`Excisão cirúrgica ampla com margens de segurança, associada a crioterapia ou eletrocauterização.`,`Apenas antibioticoterapia.`,`Observação sem intervenção.`,`Apenas excisão sem margens.`,`Radioterapia isolada.`],resposta_correta:`A`,explicacao:`O tratamento do sarcóide requer excisão cirúrgica ampla com margens de segurança, frequentemente associada a crioterapia, eletrocauterização ou quimioterapia tópica para reduzir recidiva. Antibioticoterapia (B) não é indicada. Observação (C) permite crescimento. Sem margens (D) tem alta recidiva. Radioterapia (E) é complementar.`},{id:`cga-c-147`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Granulação exuberante em bovinos`,dificuldade:`medio`,enunciado:`A granulação exuberante em bovinos é:`,alternativas:[`Menos comum que em equinos, mas pode ocorrer em feridas de membros.`,`Mais comum que em equinos.`,`Exclusiva de equinos.`,`Tratada apenas com antibioticoterapia.`,`Contraindicação para sutura.`],resposta_correta:`A`,explicacao:`A granulação exuberante é menos comum em bovinos que em equinos, mas pode ocorrer em feridas de membros. Não é mais comum (B), exclusiva de equinos (C), tratada apenas com antibióticos (D) nem contraindicação para sutura (E).`},{id:`cga-c-148`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Cobertura de feridas em equinos`,dificuldade:`medio`,enunciado:`Para cobertura de feridas em equinos, é recomendado:`,alternativas:[`Bandagem não aderente com antimicrobiano tópico, trocada a cada 24-48 horas.`,`Bandagem oclusiva sem troca por 7 dias.`,`Exposição ao ar sem bandagem.`,`Aplicação de óleo de cozinha.`,`Cobertura com terra ou pó.`],resposta_correta:`A`,explicacao:`A bandagem não aderente com antimicrobiano tópico, trocada regularmente (24-48h), é recomendada para feridas em equinos, mantendo ambiente úmido e protegido. Oclusiva prolongada (B), exposição (C), óleo (D) e terra (E) são inadequados.`},{id:`cga-c-149`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`cirurgia_tegumentar_ga`,subtopico:`Epitelioma cutâneo em bovinos`,dificuldade:`medio`,enunciado:`O carcinoma de células escamosas (CCE) em bovinos afeta mais frequentemente:`,alternativas:[`Os olhos (pálpebras, membrana nictitante) em animais de pelagem clara.`,`A pele do abdome.`,`A pele dos membros.`,`A pele do dorso.`,`A pele da cabeça (exceto olhos).`],resposta_correta:`A`,explicacao:`O CCE em bovinos afeta mais frequentemente os olhos (pálpebras, membrana nictitante, córnea) em animais de pelagem clara, devido à exposição à radiação UV. Abdome (B), membros (C), dorso (D) e cabeça (E) são menos acometidos.`},{id:`cga-c-150`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Sutura de tendão em equinos`,dificuldade:`dificil`,enunciado:`A sutura de tendão em equinos requer:`,alternativas:[`Fio absorvível de alta resistência (poliglactina 910 ou ácido poliglicólico) e técnica de Bunnell ou Kessler.`,`Fio de seda trançada.`,`Fio de catgut simples.`,`Fio de nylon monofilamentar fino.`,`Fio de aço inoxidável.`],resposta_correta:`A`,explicacao:`A sutura de tendão requer fio absorvível de alta resistência (poliglactina 910 ou ácido poliglicólico) e técnicas como Bunnell ou Kessler, que distribuem a tensão uniformemente. Seda (B) adere bactérias. Catgut (C) é reativo. Nylon (D) não é absorvível. Aço (E) é difícil.`},{id:`cga-c-151`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Crioterapia em equinos`,dificuldade:`medio`,enunciado:`A crioterapia (nitrogênio líquido) em equinos é utilizada para:`,alternativas:[`Tratamento de sarcóides, papilomas e outras lesões cutâneas.`,`Tratamento de fraturas ósseas.`,`Tratamento de artrite.`,`Tratamento de tendinite.`,`Tratamento de laminite.`],resposta_correta:`A`,explicacao:`A crioterapia com nitrogênio líquido é utilizada para tratamento de lesões cutâneas como sarcóides, papilomas e verrugas, causando destruição celular pelo frio. Não é para fraturas (B), artrite (C), tendinite (D) ou laminite (E).`},{id:`cga-c-152`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`cirurgia_tegumentar_ga`,subtopico:`Laser em cirurgia de grandes animais`,dificuldade:`medio`,enunciado:`O uso de laser (CO2 ou diodo) em cirurgia de grandes animais é indicado para:`,alternativas:[`Excisão de lesões cutâneas, hemostasia e vaporização de tecidos.`,`Tratamento de fraturas.`,`Tratamento de artrite.`,`Tratamento de cólica.`,`Tratamento de pneumonia.`],resposta_correta:`A`,explicacao:`O laser é utilizado para excisão de lesões cutâneas, hemostasia (coagulação) e vaporização de tecidos, proporcionando menor sangramento e dor pós-operatória. Não é para fraturas (B), artrite (C), cólica (D) ou pneumonia (E).`},{id:`cga-c-153`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`cirurgia_tegumentar_ga`,subtopico:`Eletrocauterização em equinos`,dificuldade:`medio`,enunciado:`A eletrocauterização em cirurgia de equinos é utilizada para:`,alternativas:[`Hemostasia, remoção de lesões cutâneas e desbridamento de tecido necrótico.`,`Tratamento de fraturas.`,`Tratamento de artrite.`,`Tratamento de cólica.`,`Tratamento de pneumonia.`],resposta_correta:`A`,explicacao:`A eletrocauterização é utilizada para hemostasia (controle de sangramento), remoção de lesões cutâneas e desbridamento de tecido necrótico. Não é para fraturas (B), artrite (C), cólica (D) ou pneumonia (E).`},{id:`cga-c-154`,banca:`ENAV`,ano:2023,prova:`ENAV — Complicações 2023`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Hemorragia cirúrgica`,dificuldade:`medio`,enunciado:`O controle de hemorragia arterial em cirurgia de grandes animais é realizado por:`,alternativas:[`Ligadura com fio absorvível ou não absorvível, aplicada proximalmente ao ponto de sangramento.`,`Apenas compressão digital.`,`Apenas eletrocoagulação.`,`Apenas agentes hemostáticos locais.`,`Observação sem intervenção.`],resposta_correta:`A`,explicacao:`A ligadura é o método definitivo para controle de hemorragia arterial, aplicando o fio proximalmente ao sangramento. Compressão (B) é temporária. Eletrocoagulação (C) é para capilares. Hemostáticos (D) são coadjuvantes. Observação (E) é inadequada.`},{id:`cga-c-155`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Infecção de ferida cirúrgica`,dificuldade:`medio`,enunciado:`A infecção de ferida cirúrgica em equinos é mais comumente:`,alternativas:[`Causada por Staphylococcus aureus e Streptococcus spp., prevenida por assepsia adequada.`,`Causada por vírus.`,`Causada por fungos.`,`Causada por parasitas.`,`Autolimitante sem tratamento.`],resposta_correta:`A`,explicacao:`A infecção de ferida cirúrgica em equinos é mais comumente causada por bactérias (Staphylococcus aureus, Streptococcus spp.), prevenida por assepsia adequada e antibioticoterapia profilática. Não é viral (B), fúngica (C), parasitária (D) nem autolimitante (E).`},{id:`cga-c-156`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Deiscência de sutura`,dificuldade:`medio`,enunciado:`A deiscência (ruptura) de sutura em feridas cirúrgicas de equinos é:`,alternativas:[`Complicação comum, frequentemente causada por tensão excessiva, infecção ou granulação exuberante.`,`Raramente observada em equinos.`,`Sempre causada por trauma.`,`Tratada apenas com antibioticoterapia.`,`Prevenida apenas com bandagem.`],resposta_correta:`A`,explicacao:`A deiscência é complicação comum em equinos, causada por tensão excessiva, infecção, granulação exuberante ou trauma. Não é rara (B), sempre traumática (C), tratada apenas com antibióticos (D) nem prevenida apenas com bandagem (E).`},{id:`cga-c-157`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Peritonite em equinos`,dificuldade:`dificil`,enunciado:`A peritonite pós-cirúrgica em equinos é:`,alternativas:[`Complicação grave, frequentemente fatal, causada por contaminação da cavidade peritoneal.`,`Complicação leve, autolimitante.`,`Raramente observada após cirurgia abdominal.`,`Tratada apenas com fluidoterapia.`,`Prevenida apenas com antibioticoterapia.`],resposta_correta:`A`,explicacao:`A peritonite é complicação grave e frequentemente fatal, causada por contaminação da cavidade peritoneal (vazamento anastomótico, perfuração). Não é leve (B), rara (C), tratada apenas com fluidoterapia (D) nem prevenida apenas com antibióticos (E).`},{id:`cga-c-158`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Sepse em grandes animais`,dificuldade:`dificil`,enunciado:`A sepse em grandes animais pós-cirúrgica é:`,alternativas:[`Resposta sistêmica a infecção, com febre, taquicardia, leucocitose e disfunção orgânica.`,`Apenas febre localizada.`,`Apenas leucocitose sem sinais sistêmicos.`,`Apenas taquicardia sem infecção.`,`Apenas disfunção renal.`],resposta_correta:`A`,explicacao:`A sepse é resposta sistêmica a infecção, caracterizada por febre, taquicardia, leucocitose e disfunção orgânica. Não é apenas febre localizada (B), leucocitose (C), taquicardia (D) ou disfunção renal (E).`},{id:`cga-c-159`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Choque hipovolêmico em equinos`,dificuldade:`medio`,enunciado:`O choque hipovolêmico em equinos é causado por:`,alternativas:[`Perda aguda de volume sanguíneo ou fluidos, com redução da perfusão tecidual.`,`Apenas febre.`,`Apenas dor.`,`Apenas infecção.`,`Apenas desidratação leve.`],resposta_correta:`A`,explicacao:`O choque hipovolêmico é causado por perda aguda de volume sanguíneo (hemorragia) ou fluidos (desidratação severa), com redução da perfusão tecidual. Não é apenas febre (B), dor (C), infecção (D) ou desidratação leve (E).`},{id:`cga-c-160`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Tromboflebite em equinos`,dificuldade:`dificil`,enunciado:`A tromboflebite (infecção de veia jugular) em equinos é:`,alternativas:[`Complicação comum de cateterização venosa, causando edema, dor e obstrução da veia.`,`Raramente observada em equinos.`,`Tratada apenas com anti-inflamatórios.`,`Sempre bilateral.`,`Contraindicação para antibioticoterapia.`],resposta_correta:`A`,explicacao:`A tromboflebite é complicação comum de cateterização venosa prolongada, causando edema, dor, calor e obstrução da veia jugular. Não é rara (B), tratada apenas com anti-inflamatórios (C), sempre bilateral (D) nem contraindicação para antibióticos (E).`},{id:`cga-c-161`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Miopatia por compressão em equinos`,dificuldade:`dificil`,enunciado:`A miopatia por compressão em equinos anestesiados é:`,alternativas:[`Lesão muscular causada por isquemia durante decúbito prolongado, podendo levar a rabdomiólise.`,`Infecção muscular bacteriana.`,`Tumor muscular.`,`Lesão nervosa periférica.`,`Fratura muscular.`],resposta_correta:`A`,explicacao:`A miopatia por compressão é lesão muscular causada por isquemia durante decúbito prolongado em equinos anestesiados, podendo levar a rabdomiólise e sequelas permanentes. Não é infecção (B), tumor (C), lesão nervosa (D) ou fratura (E).`},{id:`cga-c-162`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Fístula de sutura em bovinos`,dificuldade:`medio`,enunciado:`A fístula de sutura (abscesso no ponto de sutura) em bovinos é:`,alternativas:[`Complicação comum, causada por infecção no trajeto do fio de sutura.`,`Raramente observada em bovinos.`,`Tratada apenas com remoção do fio.`,`Sempre autolimitante.`,`Contraindicação para nova sutura.`],resposta_correta:`A`,explicacao:`A fístula de sutura é complicação comum em bovinos, causada por infecção no trajeto do fio de sutura, frequentemente associada a fio não absorvível. Não é rara (B), apenas remoção (C) é insuficiente, nem sempre autolimitante (D) nem contraindicação (E).`},{id:`cga-c-163`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Edema pós-cirúrgico em equinos`,dificuldade:`medio`,enunciado:`O edema pós-cirúrgico em equinos é:`,alternativas:[`Resposta inflamatória esperada, controlada com anti-inflamatórios, bandagem e exercício leve.`,`Sempre indicação de infecção.`,`Tratado apenas com antibioticoterapia.`,`Sempre autolimitante.`,`Contraindicação para exercício.`],resposta_correta:`A`,explicacao:`O edema pós-cirúrgico é resposta inflamatória esperada, controlada com anti-inflamatórios, bandagem compressiva e exercício leve. Não é sempre infecção (B), tratado apenas com antibióticos (C), sempre autolimitante (D) nem contraindicação para exercício (E).`},{id:`cga-c-164`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Hematoma pós-cirúrgico`,dificuldade:`medio`,enunciado:`O hematoma pós-cirúrgico em equinos é:`,alternativas:[`Acúmulo de sangue no espaço subcutâneo, controlado com drenagem e bandagem compressiva.`,`Sempre indicação de hemorragia interna.`,`Tratado apenas com antibioticoterapia.`,`Sempre autolimitante.`,`Contraindicação para nova cirurgia.`],resposta_correta:`A`,explicacao:`O hematoma é acúmulo de sangue no espaço subcutâneo, controlado com drenagem (se necessário) e bandagem compressiva. Não é sempre hemorragia interna (B), tratado apenas com antibióticos (C), sempre autolimitante (D) nem contraindicação (E).`},{id:`cga-c-165`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Sérisa em bovinos`,dificuldade:`medio`,enunciado:`A sérisa (acúmulo de líquido seroso) em feridas cirúrgicas de bovinos é:`,alternativas:[`Complicação comum, causada por espaço morto no sítio cirúrgico, tratada com drenagem.`,`Sempre indicação de infecção.`,`Tratada apenas com antibioticoterapia.`,`Sempre autolimitante.`,`Contraindicação para nova cirurgia.`],resposta_correta:`A`,explicacao:`A sérisa é complicação comum causada por espaço morto no sítio cirúrgico, com acúmulo de líquido seroso, tratada com drenagem e bandagem compressiva. Não é sempre infecção (B), apenas antibióticos (C), sempre autolimitante (D) nem contraindicação (E).`},{id:`cga-c-166`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Ruptura de anastomose em equinos`,dificuldade:`dificil`,enunciado:`A ruptura de anastomose intestinal em equinos é:`,alternativas:[`Complicação grave e frequentemente fatal, causada por falha na sutura ou infecção.`,`Complicação leve, autolimitante.`,`Raramente observada após cirurgia intestinal.`,`Tratada apenas com fluidoterapia.`,`Prevenida apenas com antibioticoterapia.`],resposta_correta:`A`,explicacao:`A ruptura de anastomose é complicação grave e frequentemente fatal, causada por falha na sutura, infecção ou deiscência, com contaminação peritoneal. Não é leve (B), rara (C), tratada apenas com fluidoterapia (D) nem prevenida apenas com antibióticos (E).`},{id:`cga-c-167`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Adesões peritoneais`,dificuldade:`medio`,enunciado:`As aderências peritoneais pós-cirúrgicas em equinos podem causar:`,alternativas:[`Obstrução intestinal e recorrência de cólica.`,`Apenas dor abdominal.`,`Apenas febre.`,`Apenas diarreia.`,`Apenas taquicardia.`],resposta_correta:`A`,explicacao:`As aderências peritoneais podem causar obstrução intestinal e recorrência de cólica, sendo complicação importante de cirurgias abdominais em equinos. Dor (B), febre (C), diarreia (D) e taquicardia (E) são sinais inespecíficos.`},{id:`cga-c-168`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Desidratação pós-cirúrgica`,dificuldade:`medio`,enunciado:`A desidratação pós-cirúrgica em equinos é:`,alternativas:[`Complicação comum, causada por perda de fluidos durante a cirurgia e redução da ingestão hídrica.`,`Sempre indicação de insuficiência renal.`,`Tratada apenas com fluidoterapia intravenosa.`,`Sempre autolimitante.`,`Contraindicação para alimentação.`],resposta_correta:`A`,explicacao:`A desidratação pós-cirúrgica é complicação comum, causada por perda de fluidos durante a cirurgia e redução da ingestão hídrica, tratada com fluidoterapia. Não é sempre insuficiência renal (B), apenas intravenosa (C), sempre autolimitante (D) nem contraindicação para alimentação (E).`},{id:`cga-c-169`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Hipotermia em equinos anestesiados`,dificuldade:`medio`,enunciado:`A hipotermia em equinos durante anestesia geral é:`,alternativas:[`Complicação comum, causada por perda de calor durante cirurgia prolongada e vasodilatação.`,`Raramente observada em equinos.`,`Sempre benigna.`,`Tratada apenas com aquecimento ambiental.`,`Contraindicação para extubação.`],resposta_correta:`A`,explicacao:`A hipotermia é complicação comum durante anestesia geral em equinos, causada por perda de calor durante cirurgia prolongada e vasodilatação por anestésicos. Não é rara (B), sempre benigna (C), apenas ambiental (D) nem contraindicação para extubação (E).`},{id:`cga-c-170`,banca:`UFRPE`,ano:2021,prova:`UFRPE — Concurso 2021`,tipo:`concurso`,topico:`complicacoes_cirurgicas_ga`,subtopico:`Complicações de castração em equinos`,dificuldade:`medio`,enunciado:`As complicações mais comuns da castração em equinos são:`,alternativas:[`Hemorragia, infecção, prolapso de intestino e edema escrotal.`,`Apenas dor pós-operatória.`,`Apenas infecção.`,`Apenas hemorragia.`,`Apenas edema.`],resposta_correta:`A`,explicacao:`As complicações mais comuns da castração incluem hemorragia, infecção, prolapso de intestino (emergência) e edema escrotal. Não são apenas dor (B), infecção (C), hemorragia (D) ou edema (E).`},{id:`cga-c-171`,banca:`ENAV`,ano:2023,prova:`ENAV — Instrumentação 2023`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para laparotomia`,dificuldade:`medio`,enunciado:`Para laparotomia em bovinos, os instrumentos essenciais são:`,alternativas:[`Bisturi, tesoura cirúrgica, pinças hemostáticas, afastadores e fios de sutura.`,`Apenas bisturi e tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`,`Apenas afastadores.`],resposta_correta:`A`,explicacao:`A laparotomia requer bisturi (incisão), tesoura (corte), pinças hemostáticas (controle de hemorragia), afastadores (exposição) e fios de sutura (fechamento). Apenas bisturi e tesoura (B) são insuficientes. Pinças (C), fios (D) e afastadores (E) isoladamente são insuficientes.`},{id:`cga-c-172`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para ortopedia`,dificuldade:`medio`,enunciado:`Para osteossíntese em grandes animais, os instrumentos específicos incluem:`,alternativas:[`Serra oscilatória, perfurador ósseo, parafusos, placas e fios de Kirschner.`,`Apenas bisturi e tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`,`Apenas afastadores.`],resposta_correta:`A`,explicacao:`A osteossíntese requer instrumentos específicos como serra oscilatória (corte ósseo), perfurador ósseo (confecção de orifícios), parafusos, placas e fios de Kirschner. Bisturi (B), pinças (C), fios (D) e afastadores (E) são instrumentos gerais.`},{id:`cga-c-173`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Contenção mecânica`,dificuldade:`medio`,enunciado:`Para contenção mecânica de bovinos em cirurgia de campo, é utilizado:`,alternativas:[`Tronco de contenção (squeeze chute), valeta e cordas.`,`Apenas cordas.`,`Apenas tronco de contenção.`,`Apenas valeta.`,`Apenas contenção química.`],resposta_correta:`A`,explicacao:`A contenção mecânica de bovinos em campo utiliza tronco de contenção (squeeze chute), valeta (para decúbito) e cordas (fixação de membros). Cordas (B), tronco (C) e valeta (D) isoladamente são insuficientes. Contenção química (E) é complementar.`},{id:`cga-c-174`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para rumenotomia`,dificuldade:`medio`,enunciado:`Para rumenotomia em bovinos, além dos instrumentos de laparotomia, é necessário:`,alternativas:[`Pinça de Allis ou Backhaus para fixação do rúmen e recipiente para coleta de conteúdo ruminal.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`],resposta_correta:`A`,explicacao:`A rumenotomia requer pinças de Allis ou Backhaus para fixação do rúmen à parede abdominal e recipiente para coleta de conteúdo ruminal. Bisturi (B), tesoura (C), pinças (D) e fios (E) são insuficientes isoladamente.`},{id:`cga-c-175`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para castração`,dificuldade:`facil`,enunciado:`Para castração aberta em equinos, os instrumentos essenciais são:`,alternativas:[`Bisturi, pinças hemostáticas, tesoura cirúrgica e fio de sutura.`,`Apenas bisturi.`,`Apenas pinça de Burdizzo.`,`Apenas elastrador.`,`Apenas tesoura de Serra.`],resposta_correta:`A`,explicacao:`A castração aberta requer bisturi (incisão), pinças hemostáticas (hemostasia), tesoura (corte de tecidos) e fio de sutura (ligadura). Bisturi (B) isoladamente é insuficiente. Burdizzo (C), elastrador (D) e tesoura de Serra (E) são métodos alternativos.`},{id:`cga-c-176`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para artroscopia`,dificuldade:`medio`,enunciado:`Para artroscopia em equinos, os instrumentos específicos incluem:`,alternativas:[`Artroscópio, óptica, fonte de luz, bomba de irrigação e instrumental artroscópico.`,`Apenas bisturi e tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`,`Apenas afastadores.`],resposta_correta:`A`,explicacao:`A artroscopia requer artroscópio (câmera), óptica (visualização), fonte de luz (iluminação), bomba de irrigação (expansão articular) e instrumental artroscópico (pinças, tesouras). Bisturi (B), pinças (C), fios (D) e afastadores (E) são instrumentos gerais.`},{id:`cga-c-177`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para sutura`,dificuldade:`medio`,enunciado:`Para sutura de pele em grandes animais, os instrumentos recomendados são:`,alternativas:[`Porta-agulhas de Hegar ou Olsen, agulha curva e fio de nylon ou polipropileno.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas grampeador.`],resposta_correta:`A`,explicacao:`A sutura de pele requer porta-agulhas (Hegar ou Olsen para grandes animais), agulha curva e fio não absorvível (nylon ou polipropileno). Bisturi (B), tesoura (C), pinças (D) e grampeador (E) não são instrumentos de sutura.`},{id:`cga-c-178`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`instrumentacao_ga`,subtopico:`Equipamentos para anestesia`,dificuldade:`medio`,enunciado:`Para anestesia geral inalatória em equinos, o equipamento necessário inclui:`,alternativas:[`Vaporizador de isoflurano, circuito anestésico, cilindro de oxigênio e ventilador pulmonar.`,`Apenas máscara facial.`,`Apenas seringa e agulha.`,`Apenas cateter venoso.`,`Apenas sonda nasogástrica.`],resposta_correta:`A`,explicacao:`A anestesia inalatória requer vaporizador (dosagem do anestésico), circuito anestésico (condução dos gases), cilindro de oxigênio (suprimento) e ventilador pulmonar (ventilação). Máscara (B), seringa (C), cateter (D) e sonda (E) são acessórios.`},{id:`cga-c-179`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para toracocentese`,dificuldade:`medio`,enunciado:`Para toracocentese em equinos, os instrumentos necessários são:`,alternativas:[`Agulha de grosso calibre (14-16G), seringa, tubo de drenagem e frasco coletor.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`],resposta_correta:`A`,explicacao:`A toracocentese requer agulha de grosso calibre (14-16G), seringa (aspiração), tubo de drenagem (evacuação de líquido) e frasco coletor (coleta). Bisturi (B), tesoura (C), pinças (D) e fios (E) não são utilizados.`},{id:`cga-c-180`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para desacornamento`,dificuldade:`facil`,enunciado:`Para desacornamento em bezerros, os instrumentos utilizados são:`,alternativas:[`Termocauter (broca de desacornamento) ou serra de Guthrie, e anestésico local.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas elastrador.`],resposta_correta:`A`,explicacao:`O desacornamento utiliza termocauter (broca) ou serra de Guthrie (para desacornamento a frio), e anestésico local (lidocaína). Bisturi (B), tesoura (C), pinças (D) e elastrador (E) não são instrumentos de desacornamento.`},{id:`cga-c-181`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Equipamentos para radiografia`,dificuldade:`medio`,enunciado:`Para radiografia de grandes animais em campo, é necessário:`,alternativas:[`Equipamento de radiografia portátil, chapa radiográfica ou detector digital e equipamento de proteção.`,`Apenas ultrassom.`,`Apenas endoscópio.`,`Apenas estetoscópio.`,`Apenas termômetro.`],resposta_correta:`A`,explicacao:`A radiografia de campo requer equipamento portátil (gerador de raios X), chapa ou detector digital (captura da imagem) e equipamento de proteção (aventais, luvas, óculos). Ultrassom (B), endoscópio (C), estetoscópio (D) e termômetro (E) são outros equipamentos.`},{id:`cga-c-182`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para drenagem`,dificuldade:`medio`,enunciado:`Para drenagem torácica em equinos, os instrumentos utilizados são:`,alternativas:[`Dreno de Penrose ou dreno torácico fechado, trocante, bisturi e fio de sutura.`,`Apenas agulha.`,`Apenas seringa.`,`Apenas cateter venoso.`,`Apenas sonda nasogástrica.`],resposta_correta:`A`,explicacao:`A drenagem torácica requer dreno (Penrose ou fechado), trocante (inserção), bisturi (incisão) e fio (fixação do dreno). Agulha (B), seringa (C), cateter (D) e sonda (E) não são instrumentos de drenagem torácica.`},{id:`cga-c-183`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para exame retal`,dificuldade:`medio`,enunciado:`Para exame retal em equinos, é necessário:`,alternativas:[`Luva de palpação retal, lubrificante e avental descartável.`,`Apenas estetoscópio.`,`Apenas termômetro.`,`Apenas otoscópio.`,`Apenas oftalmoscópio.`],resposta_correta:`A`,explicacao:`O exame retal requer luva de palpação retal (proteção), lubrificante (facilitação da inserção) e avental descartável (higiene). Estetoscópio (B), termômetro (C), otoscópio (D) e oftalmoscópio (E) não são utilizados para exame retal.`},{id:`cga-c-184`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Equipamentos para endoscopia`,dificuldade:`medio`,enunciado:`Para endoscopia gastrointestinal em equinos, o equipamento necessário inclui:`,alternativas:[`Endoscópio flexível de 1,5-3 metros, fonte de luz, monitor e bomba de insuflação.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas fios de sutura.`],resposta_correta:`A`,explicacao:`A endoscopia gastrointestinal requer endoscópio flexível (comprimento adequado para cólon), fonte de luz (iluminação), monitor (visualização) e bomba de insuflação (expansão da luz intestinal). Bisturi (B), tesoura (C), pinças (D) e fios (E) não são instrumentos endoscópicos.`},{id:`cga-c-185`,banca:`UFPR`,ano:2023,prova:`UFPR — Concurso 2023`,tipo:`concurso`,topico:`instrumentacao_ga`,subtopico:`Instrumentos para herniorrafia`,dificuldade:`medio`,enunciado:`Para herniorrafia em grandes animais, além dos instrumentos de laparotomia, é necessário:`,alternativas:[`Tela de polipropileno ou poliéster, fios não absorvíveis e instrumentais de sutura.`,`Apenas bisturi.`,`Apenas tesoura.`,`Apenas pinças hemostáticas.`,`Apenas grampeador.`],resposta_correta:`A`,explicacao:`A herniorrafia com reforço protético requer tela (polipropileno ou poliéster), fios não absorvíveis (fixação da tela) e instrumentais de sutura (porta-agulhas, agulhas). Bisturi (B), tesoura (C), pinças (D) e grampeador (E) são insuficientes.`},{id:`cga-c-186`,banca:`UFRGS`,ano:2022,prova:`UFRGS — Residência 2022`,tipo:`residencia`,topico:`instrumentacao_ga`,subtopico:`Equipamentos para ultrassonografia`,dificuldade:`medio`,enunciado:`Para ultrassonografia abdominal em equinos, o transdutor mais utilizado é:`,alternativas:[`Transdutor convexo de 3,5-5 MHz para abdome e linear de 7,5-10 MHz para estruturas superficiais.`,`Apenas transdutor linear.`,`Apenas transdutor setorial.`,`Apenas transdutor endocavitário.`,`Apenas transdutor de Doppler.`],resposta_correta:`A`,explicacao:`A ultrassonografia abdominal em equinos utiliza transdutor convexo de 3,5-5 MHz (penetração profunda) e linear de 7,5-10 MHz (estruturas superficiais). Transdutor linear (B), setorial (C), endocavitário (D) e Doppler (E) têm indicações específicas.`},{id:`cga-c-187`,banca:`ENAV`,ano:2023,prova:`ENAV — Pós-Operatório 2023`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Cuidados pós-operatórios`,dificuldade:`medio`,enunciado:`Os cuidados pós-operatórios essenciais em equinos incluem:`,alternativas:[`Monitoramento de sinais vitais, controle de dor, antibioticoterapia e exercício supervisionado.`,`Apenas antibioticoterapia.`,`Apenas controle de dor.`,`Apenas exercício supervisionado.`,`Apenas monitoramento.`],resposta_correta:`A`,explicacao:`Os cuidados pós-operatórios incluem monitoramento (sinais vitais, ferida), controle de dor (analgésicos), antibioticoterapia (prevenção de infecção) e exercício supervisionado (recuperação). Antibioticoterapia (B), dor (C), exercício (D) e monitoramento (E) isoladamente são insuficientes.`},{id:`cga-c-188`,banca:`CESPE`,ano:2022,prova:`CESPE — Concurso 2022`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Analgesia em equinos`,dificuldade:`medio`,enunciado:`A analgesia pós-cirúrgica em equinos é:`,alternativas:[`Essencial para bem-estar e recuperação, utilizando AINES, opioides e técnicas locais.`,`Opcional, sem impacto na recuperação.`,`Contraindicada por risco de efeitos adversos.`,`Apenas com anti-inflamatórios não esteroidais.`,`Apenas com opioides.`],resposta_correta:`A`,explicacao:`A analgesia é essencial para bem-estar e recuperação, utilizando AINES (flunixin, fenilbutazona), opioides (butorfanol) e técnicas locais (bloqueios). Não é opcional (B), contraindicada (C), apenas AINES (D) ou apenas opioides (E).`},{id:`cga-c-189`,banca:`FCC`,ano:2021,prova:`FCC — Concurso 2021`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Antibioticoterapia pós-cirúrgica`,dificuldade:`medio`,enunciado:`A antibioticoterapia pós-cirúrgica em grandes animais é:`,alternativas:[`Indicada para prevenção de infecção em cirurgias contaminadas ou em pacientes imunodeprimidos.`,`Obrigatória em toda cirurgia.`,`Contraindicada por risco de resistência bacteriana.`,`Apenas em cirurgias ortopédicas.`,`Apenas em cirurgias abdominais.`],resposta_correta:`A`,explicacao:`A antibioticoterapia profilática é indicada em cirurgias contaminadas, procedimentos de alto risco ou pacientes imunodeprimidos. Não é obrigatória (B), contraindicada (C), apenas ortopédicas (D) ou apenas abdominais (E).`},{id:`cga-c-190`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso 2023`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Reabilitação de equinos`,dificuldade:`medio`,enunciado:`A reabilitação pós-cirúrgica em equinos inclui:`,alternativas:[`Exercício supervisionado, fisioterapia, hidroterapia e controle de retorno à atividade.`,`Apenas repouso absoluto.`,`Apenas exercício livre.`,`Apenas fisioterapia.`,`Apenas controle de retorno.`],resposta_correta:`A`,explicacao:`A reabilitação inclui exercício supervisionado (progressivo), fisioterapia (alongamento, fortalecimento), hidroterapia (esteira d'água) e controle de retorno à atividade. Repouso absoluto (B), exercício livre (C), apenas fisioterapia (D) e controle (E) são insuficientes.`},{id:`cga-c-191`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Cirurgia 2020`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Fluidoterapia pós-cirúrgica`,dificuldade:`medio`,enunciado:`A fluidoterapia pós-cirúrgica em equinos é:`,alternativas:[`Essencial para manutenção da hidratação, correção de desequilíbrios eletrolíticos e suporte hemodinâmico.`,`Opcional, sem impacto na recuperação.`,`Contraindicada por risco de sobrecarga volêmica.`,`Apenas com soro fisiológico.`,`Apenas com Ringer lactato.`],resposta_correta:`A`,explicacao:`A fluidoterapia é essencial para manutenção da hidratação, correção de desequilíbrios eletrolíticos e suporte hemodinâmico. Não é opcional (B), contraindicada (C), apenas SF (D) ou apenas Ringer (E).`},{id:`cga-c-192`,banca:`CRMV`,ano:2022,prova:`CRMV — Suficiência 2022`,tipo:`crmv`,topico:`pos_operatorio_ga`,subtopico:`Cuidados com ferida cirúrgica`,dificuldade:`medio`,enunciado:`Os cuidados com a ferida cirúrgica em equinos incluem:`,alternativas:[`Limpeza diária, aplicação de antimicrobiano tópico, bandagem e monitoramento de sinais de infecção.`,`Apenas antibioticoterapia sistêmica.`,`Apenas limpeza com água.`,`Apenas bandagem.`,`Apenas observação.`],resposta_correta:`A`,explicacao:`Os cuidados com ferida incluem limpeza diária (soro fisiológico), antimicrobiano tópico, bandagem (proteção) e monitoramento (infecção, deiscência). Antibioticoterapia (B), água (C), bandagem (D) e observação (E) isoladamente são insuficientes.`},{id:`cga-c-193`,banca:`UFMG`,ano:2021,prova:`UFMG — Concurso 2021`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Alimentação pós-cirúrgica`,dificuldade:`medio`,enunciado:`A alimentação pós-cirúrgica em equinos deve:`,alternativas:[`Ser reintroduzida gradualmente, iniciando com feno de boa qualidade e água à vontade.`,`Ser suspensa por 48 horas.`,`Ser apenas com ração concentrada.`,`Ser apenas com capim fresco.`,`Ser apenas com suplementos vitamínicos.`],resposta_correta:`A`,explicacao:`A alimentação deve ser reintroduzida gradualmente, iniciando com feno de boa qualidade (fibra) e água à vontade. Suspensão (B), concentrado (C), capim fresco (D) e vitaminas (E) isoladamente são inadequados.`},{id:`cga-c-194`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência 2023`,tipo:`residencia`,topico:`pos_operatorio_ga`,subtopico:`Retorno à atividade em equinos`,dificuldade:`medio`,enunciado:`O retorno à atividade após cirurgia ortopédica em equinos deve:`,alternativas:[`Ser gradual, supervisionado por veterinário, com avaliação clínica e imagem antes de liberar exercício completo.`,`Ser imediato após a cirurgia.`,`Ser após 12 meses de repouso.`,`Ser apenas após avaliação do proprietário.`,`Ser apenas com exercício leve.`],resposta_correta:`A`,explicacao:`O retorno à atividade deve ser gradual, supervisionado por veterinário, com avaliação clínica e imagem (radiografia, ultrassonografia) antes de liberar exercício completo. Imediato (A) é inadequado. 12 meses (C) é excessivo. Proprietário (D) e leve (E) são insuficientes.`},{id:`cga-c-195`,banca:`USP`,ano:2022,prova:`USP — Residência 2022`,tipo:`residencia`,topico:`pos_operatorio_ga`,subtopico:`Monitoramento pós-anestésico`,dificuldade:`medio`,enunciado:`O monitoramento pós-anestésico em equinos inclui:`,alternativas:[`Sinais vitais (FC, FR, T°), nível de consciência, função respiratória e controle de dor.`,`Apenas frequência cardíaca.`,`Apenas temperatura.`,`Apenas nível de consciência.`,`Apenas função respiratória.`],resposta_correta:`A`,explicacao:`O monitoramento pós-anestésico inclui sinais vitais (FC, FR, T°), nível de consciência, função respiratória e controle de dor. FC (B), temperatura (C), consciência (D) e respiração (E) isoladamente são insuficientes.`},{id:`cga-c-196`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Concurso 2021`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Complicações pós-operatórias precoces`,dificuldade:`medio`,enunciado:`As complicações pós-operatórias precoces em equinos incluem:`,alternativas:[`Hemorragia, infecção, edema, dor e choque.`,`Apenas dor.`,`Apenas infecção.`,`Apenas hemorragia.`,`Apenas edema.`],resposta_correta:`A`,explicacao:`As complicações precoces incluem hemorragia, infecção, edema, dor e choque. Dor (B), infecção (C), hemorragia (D) e edema (E) isoladamente são insuficientes.`},{id:`cga-c-197`,banca:`MAPA`,ano:2023,prova:`MAPA — Fiscal 2023`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Cuidados pós-operatórios em bovinos`,dificuldade:`medio`,enunciado:`Os cuidados pós-operatórios em bovinos incluem:`,alternativas:[`Monitoramento de sinais vitais, controle de dor, antibioticoterapia e manejo alimentar adequado.`,`Apenas antibioticoterapia.`,`Apenas controle de dor.`,`Apenas manejo alimentar.`,`Apenas monitoramento.`],resposta_correta:`A`,explicacao:`Os cuidados pós-operatórios em bovinos incluem monitoramento (sinais vitais), controle de dor (analgésicos), antibioticoterapia (prevenção) e manejo alimentar (nutrição adequada). Antibioticoterapia (B), dor (C), alimentação (D) e monitoramento (E) isoladamente são insuficientes.`},{id:`cga-c-198`,banca:`UFMT`,ano:2020,prova:`UFMT — Concurso 2020`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Eutanásia em grandes animais`,dificuldade:`dificil`,enunciado:`A eutanásia em grandes animais está indicada quando:`,alternativas:[`Há sofrimento incurável, prognóstico desfavorável e qualidade de vida comprometida.`,`O animal apresenta apenas dor aguda.`,`O animal apresenta apenas fratura simples.`,`O animal apresenta apenas infecção.`,`O animal apresenta apenas claudicação.`],resposta_correta:`A`,explicacao:`A eutanásia está indicada quando há sofrimento incurável, prognóstico desfavorável e qualidade de vida comprometida, após avaliação veterinária cuidadosa. Dor aguda (B), fratura simples (C), infecção (D) e claudicação (E) são tratáveis.`},{id:`cga-c-199`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência 2022`,tipo:`residencia`,topico:`pos_operatorio_ga`,subtopico:`Qualidade de vida pós-cirúrgica`,dificuldade:`medio`,enunciado:`A avaliação da qualidade de vida pós-cirúrgica em grandes animais deve considerar:`,alternativas:[`Capacidade de alimentação, locomoção, interação social e ausência de dor.`,`Apenas capacidade de alimentação.`,`Apenas locomoção.`,`Apenas interação social.`,`Apenas ausência de dor.`],resposta_correta:`A`,explicacao:`A qualidade de vida deve ser avaliada considerando capacidade de alimentação, locomoção, interação social e ausência de dor. Alimentação (B), locomoção (C), interação (D) e dor (E) isoladamente são insuficientes.`},{id:`cga-c-200`,banca:`UFPE`,ano:2021,prova:`UFPE — Concurso 2021`,tipo:`concurso`,topico:`pos_operatorio_ga`,subtopico:`Alta hospitalar em equinos`,dificuldade:`medio`,enunciado:`A alta hospitalar de equinos após cirurgia é liberada quando:`,alternativas:[`O animal está estável, com dor controlada, ferida em cicatrização adequada e sem complicações.`,`O proprietário solicita.`,`O animal come normalmente.`,`O animal anda normalmente.`,`O animal não apresenta febre.`],resposta_correta:`A`,explicacao:`A alta é liberada quando o animal está estável (sinais vitais normais), com dor controlada, ferida em cicatrização adequada e sem complicações. Proprietário (B), alimentação (C), locomoção (D) e febre (E) isoladamente são critérios insuficientes.`}],i={total_questoes:r.length,por_banca:Object.keys(e).reduce((e,t)=>(e[t]=r.filter(e=>e.banca===t).length,e),{}),por_topico:Object.keys(n).reduce((e,t)=>(e[t]=r.filter(e=>e.topico===t).length,e),{}),por_dificuldade:{facil:r.filter(e=>e.dificuldade===`facil`).length,medio:r.filter(e=>e.dificuldade===`medio`).length,dificil:r.filter(e=>e.dificuldade===`dificil`).length},por_tipo:Object.keys(t).reduce((e,t)=>(e[t]=r.filter(e=>e.tipo===t).length,e),{})};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_CIRURGIA_GA,t as TIPOS_PROVA,n as TOPICOS_CIRURGIA_GA};